
/*
 * DC vs WIZKAS — ARCADE TAG FIGHTER ENGINE
 * ===========================================================================
 * Motor modular de pelea 2D por equipos (2v2) con el lenguaje de juego de los
 * arcades de Capcom de finales de los 90:
 *   - Esquema de 6 botones (LP MP HP / LK MK HK) + 2 asistencias.
 *   - Magic Series / Chain Combos (LP > MP > HP > LK > MK > HK).
 *   - Launcher + Super Jump + Aerial Rave (combo aereo / juggle).
 *   - Hiper combo gauge compartido por equipo (5 niveles) + Super Flash.
 *   - Sistema de equipos 2v2: tag switch, crossover assist, crossover
 *     combination (duo hyper), snap back, crossover counter y vida roja
 *     recuperable para el personaje en reserva.
 *   - Hitbox / hurtbox AABB, hitstop, hitstun, blockstun, pushback y
 *     advancing guard, todo normalizado a 60 Hz.
 *
 * Módulos: BOX → Input → Motion → Audio → Fx → Sprites → Moves → Fighter →
 *          Team → World → Hud → Screens → Loop.
 * ===========================================================================
 */

/* ======================= CONSTANTES GLOBALES ============================ */

const VW = 1280;              // ancho del lienzo
const VH = 720;               // alto del lienzo
const GROUND_Y = 566;         // línea de piso (pies del luchador)
const WALL_L = 70;
const WALL_R = VW - 70;
const STEP = 1 / 60;          // paso fijo de simulación (60 Hz)
const MAX_STEP_FRAMES = 5;    // techo de pasos por refresco (evita espiral)

/* Física (unidades por fotograma a 60 Hz) */
/* Dash arcade: avanza cuatro espacios de golpe. */
const DASH_SPACES = 4;
const SPACE_PX = 40;

const PHYS = {
  walkF: 8.6, walkB: 7.4,
  dashF: 30.0, dashB: 26.0,
  dashFrames: 16,
  gravity: 0.78,
  jumpVy: -15.2,
  jumpForward: 4.2,
  doubleJumpVy: -15.8,
  doubleJumpForward: 6.2,
  superJumpVy: -21.5,
  superJumpForward: 10.5,  // trayectoria larga de ↓ ↑ ↑ hacia el rival
  superJumpExtendVy: -18.5,
  superJumpFloat: 0.62,       // gravedad reducida en super salto
  maxFall: 18,                // velocidad terminal
  airDrift: 0.72,
  superJumpWindow: 12,        // fotogramas para encadenar abajo→arriba
  doubleTapWindow: 14,        // fotogramas para el doble toque de dash
  doubleJumpWindow: 18,        // ventana de arriba→arriba en el aire
  friction: 0.82,
};

/* Daño / aturdimiento genéricos */
const LIFE = 144;             // vitalidad estilo MvC
const SUPER_LEVEL = 100;      // puntos por nivel de hiper combo
const MAX_SUPER_LEVELS = 5;
const FIGHTER_DRAW_HEIGHT = 306; // altura base común para todos los luchadores

const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);
const lerp = (a, b, t) => a + (b - a) * t;
const rand = (a, b) => a + Math.random() * (b - a);
const sign = (v) => (v < 0 ? -1 : v > 0 ? 1 : 0);
const approach = (v, t, s) => (v < t ? Math.min(v + s, t) : Math.max(v - s, t));

/* ======================= CAJAS: HITBOX / HURTBOX ======================== */
/* Todas las cajas son AABB en coordenadas de personaje (origen = pies) y se
 * voltean según el facing antes de compararlas. */

function overlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function worldBox(box, f) {
  const x = f.facing === 1 ? f.x + box.x : f.x - box.x - box.w;
  return { x, y: f.y + box.y, w: box.w, h: box.h };
}

/* Une la caja del fotograma anterior y la actual. Evita que un dash, una
 * embestida o un launcher rápido atraviese al rival entre dos ticks. */
function sweptWorldBox(box, f) {
  const now = worldBox(box, f);
  if (!Number.isFinite(f.prevX) || !Number.isFinite(f.prevY)) return now;
  const old = worldBox(box, Object.assign({}, f, { x: f.prevX, y: f.prevY }));
  const x = Math.min(now.x, old.x), y = Math.min(now.y, old.y);
  return { x, y, w: Math.max(now.x + now.w, old.x + old.w) - x, h: Math.max(now.y + now.h, old.y + old.h) - y };
}

function boxCenterX(box) { return box.x + box.w / 2; }

/* ======================= ENTRADA (6 BOTONES) ============================ */

const BTN = ['lp', 'mp', 'hp', 'lk', 'mk', 'hk'];
const DIRS = ['left', 'right', 'up', 'down'];

/* Mapa de teclado. P1 usa el bloque de la izquierda, P2 las flechas. */
const KEYMAP_P1 = {
  left: 'a', right: 'd', up: 'w', down: 's',
  lp: 'j', mp: 'k', hp: 'l', lk: 'u', mk: 'i', hk: 'o',
  assistA: 'q', assistB: 'e', start: 'enter', pause: 'p',
};
const KEYMAP_P2 = {
  left: 'arrowleft', right: 'arrowright', up: 'arrowup', down: 'arrowdown',
  lp: '1', mp: '2', hp: '3', lk: '4', mk: '5', hk: '6',
  assistA: '7', assistB: '8', start: '0',
};

const PREVENT_KEYS = new Set([
  ...Object.values(KEYMAP_P1), ...Object.values(KEYMAP_P2),
  'escape', ' ', 'tab', 'shift',
]);

const Input = (() => {
  const state = {};       // teclas físicas presionadas
  const tapped = {};      // flanco de subida pendiente de consumo
  const pads = {};        // estado por jugador traducido desde teclado/mando

  window.addEventListener('keydown', (e) => {
    const k = e.key.toLowerCase();
    if (!state[k]) tapped[k] = true;
    state[k] = true;
    if (PREVENT_KEYS.has(k)) e.preventDefault();
  }, { passive: false });
  window.addEventListener('keyup', (e) => { state[e.key.toLowerCase()] = false; });
  window.addEventListener('blur', () => releaseAll());
  document.addEventListener('visibilitychange', () => { if (document.hidden) releaseAll(); });

  function releaseAll() {
    for (const k of Object.keys(state)) state[k] = false;
    for (const k of Object.keys(tapped)) tapped[k] = false;
  }

  /* Botones táctiles del tablero arcade: usan data-tk con la tecla física. */
  document.querySelectorAll('[data-tk]').forEach((b) => {
    const keys = [b.dataset.tk, ...(b.dataset.alt ? b.dataset.alt.split(',') : [])].filter(Boolean);
    const set = (v) => {
      for (const key of keys) {
        if (v && !state[key]) tapped[key] = true;
        state[key] = v;
      }
      b.classList.toggle('pressed', v);
    };
    b.addEventListener('pointerdown', (e) => { e.preventDefault(); set(true); b.setPointerCapture?.(e.pointerId); });
    b.addEventListener('pointerup', (e) => { e.preventDefault(); set(false); });
    b.addEventListener('pointercancel', () => set(false));
    b.addEventListener('lostpointercapture', () => set(false));
    b.addEventListener('pointerleave', (e) => { if (e.buttons) set(false); });
  });

  /* --- Mandos: Gamepad API (mapeo estándar) --- */
  const PAD_MAP = {
    0: 'lp', 1: 'mp', 3: 'hp',      // A, B, Y
    2: 'lk', 4: 'mk', 5: 'hk',      // X, LB, RB
    6: 'assistA', 7: 'assistB',     // LT, RT
    8: 'start', 9: 'start',
  };
  let padAxes = { 1: { x: 0, y: 0 }, 2: { x: 0, y: 0 } };

  function pollGamepads() {
    if (!navigator.getGamepads) return;
    const list = navigator.getGamepads();
    let slot = 1;
    for (const gp of list) {
      if (!gp || !gp.connected) continue;
      if (slot > 2) break;
      const p = (pads[slot] = pads[slot] || {});
      for (const b of [...BTN, 'assistA', 'assistB', 'start']) {
        p['_padPrev_' + b] = !!p['_padOn_' + b];
        p['_padOn_' + b] = false;
      }
      p._padLeft = p._padRight = p._padUp = p._padDown = false;
      gp.buttons.forEach((btn, i) => {
        if (!btn.pressed) return;
        const name = PAD_MAP[i];
        if (name) { p._pad = p._pad || {}; p['_padOn_' + name] = true; }
      });
      const ax = gp.axes[0] || 0, ay = gp.axes[1] || 0;
      padAxes[slot] = { x: Math.abs(ax) > 0.35 ? ax : 0, y: Math.abs(ay) > 0.45 ? ay : 0 };
      slot++;
    }
  }

  /* Construye el "input lógico" de un jugador para el fotograma actual.
   * `consume` = true → los flancos se consumen (solo se leen una vez). */
  function read(map, consume, playerIndex) {
    const out = { dir: { left: false, right: false, up: false, down: false }, btn: {}, tap: {}, pressed: false };
    for (const d of DIRS) out.dir[d] = !!state[map[d]];
    for (const b of BTN) out.btn[b] = !!state[map[b]];
    out.btn.assistA = !!state[map.assistA];
    out.btn.assistB = !!state[map.assistB];
    out.btn.start = !!state[map.start];

    const pad = pads[playerIndex];
    if (pad && navigator.getGamepads) {
      const axes = padAxes[playerIndex] || { x: 0, y: 0 };
      if (axes.x < 0) out.dir.left = true;
      if (axes.x > 0) out.dir.right = true;
      if (axes.y < -0.5) out.dir.up = true;
      if (axes.y > 0.5) out.dir.down = true;
      for (const b of [...BTN, 'assistA', 'assistB', 'start']) {
        if (pad['_padOn_' + b]) out.btn[b] = true;
      }
    }

    for (const b of BTN) out.tap[b] = tapped[map[b]] === true || !!(pad && pad['_padOn_' + b] && !pad['_padPrev_' + b]);
    out.tap.assistA = tapped[map.assistA] === true || !!(pad && pad._padOn_assistA && !pad._padPrev_assistA);
    out.tap.assistB = tapped[map.assistB] === true || !!(pad && pad._padOn_assistB && !pad._padPrev_assistB);
    out.tap.start = tapped[map.start] === true || !!(pad && pad._padOn_start && !pad._padPrev_start);

    out.pressed = BTN.some((b) => out.tap[b]);
    /* direcciones "tap" para dash / super salto */
    out.tapDir = {
      left: tapped[map.left] === true,
      right: tapped[map.right] === true,
      up: tapped[map.up] === true,
      down: tapped[map.down] === true,
    };
    if (pad) {
      const ax = padAxes[playerIndex]?.x || 0, ay = padAxes[playerIndex]?.y || 0;
      const px = pad._axisPrevX || 0, py = pad._axisPrevY || 0;
      out.tapDir.left ||= ax < -0.35 && px >= -0.35;
      out.tapDir.right ||= ax > 0.35 && px <= 0.35;
      out.tapDir.up ||= ay < -0.45 && py >= -0.45;
      out.tapDir.down ||= ay > 0.45 && py <= 0.45;
      pad._axisPrevX = ax; pad._axisPrevY = ay;
    }
    if (consume) {
      for (const b of [...BTN, 'assistA', 'assistB', 'start']) tapped[map[b]] = false;
      for (const d of DIRS) tapped[map[d]] = false;
    }
    return out;
  }

  return { read, releaseAll, pollGamepads, isDown: (k) => !!state[k] };
})();

/* ======================= RECONOCEDOR DE COMANDOS ======================== */
/* Guarda una línea de tiempo de las ocho direcciones (los números del teclado
 * numérico: 1..9, con 5 = neutral) y resuelve cuartos de círculo, zig-zag y
 * movimientos con carga. */

const NUM = { 4: 1, 5: 2, 6: 3, 7: 4, 8: 5, 9: 6, 1: 7, 2: 8, 3: 9 };

class MotionBuffer {
  constructor() {
    this.history = [];   // {dir: numpad 1..9, frame}
    this.frame = 0;
    this.chargeBack = 0;
    this.chargeDown = 0;
  }
  /* dir = {left,right,up,down} relativos al facing del personaje */
  push(dir, facing) {
    this.frame++;
    const l = dir.left, r = dir.right, u = dir.up, d = dir.down;
    let num = 5;
    if (d) num = l ? 1 : r ? 3 : 2;
    else if (u) num = l ? 7 : r ? 9 : 8;
    else num = l ? 4 : r ? 6 : 5;
    /* La historia se guarda ya orientada: 4 = atrás, 6 = adelante. */
    const rot = facing === 1 ? num : rotate(num);
    const last = this.history[this.history.length - 1];
    if (!last || last.dir !== rot) this.history.push({ dir: rot, frame: this.frame });
    if (this.history.length > 24) this.history.shift();

    if (dir.left && !facing === false) { /* noop, claridad */ }
    /* cargas: mantener atrás o abajo */
    const back = facing === 1 ? l : r;
    this.chargeBack = back ? this.chargeBack + 1 : 0;
    this.chargeDown = d ? this.chargeDown + 1 : 0;
  }
  /* Reconoce una secuencia de números dentro de `window` fotogramas. */
  match(seq, window = 20) {
    const now = this.frame;
    let idx = seq.length - 1;
    for (let i = this.history.length - 1; i >= 0; i--) {
      const h = this.history[i];
      if (now - h.frame > window) break;
      if (h.dir === seq[idx]) {
        idx--;
        if (idx < 0) return true;
      }
    }
    return false;
  }
  recent(maxFrames = 6) {
    const last = this.history[this.history.length - 1];
    return !!last && this.frame - last.frame <= maxFrames;
  }
  /* QCF = 2,3,6 ; QCB = 2,1,4 ; DP = 6,2,3 */
  qcf() { return this.match([2, 3, 6]); }
  qcb() { return this.match([2, 1, 4]); }
  dp() { return this.match([6, 2, 3]); }
  doubleQcf() { return this.match([2, 3, 6, 2, 3, 6], 34); }
  doubleQcb() { return this.match([2, 1, 4, 2, 1, 4], 34); }
  chargeBackOK() { return this.chargeBack >= 42; }
  chargeDownOK() { return this.chargeDown >= 42; }
  consumeChargeBack() { this.chargeBack = 0; }
  consumeChargeDown() { this.chargeDown = 0; }
  clear() { this.history.length = 0; }
}

function rotate(n) {
  switch (n) {
    case 1: return 3; case 2: return 2; case 3: return 1;
    case 4: return 6; case 5: return 5; case 6: return 4;
    case 7: return 9; case 8: return 8; case 9: return 7;
  }
  return 5;
}

/* ======================= AUDIO (Web Audio, chiptune) ==================== */

const Audio = (() => {
  let ac = null, musicGain = null, sfxGain = null, musicTimer = null, musicAudio = null;
  let musicSource = null, master = null;
  function init() {
    if (ac) return;
    const C = window.AudioContext || window.webkitAudioContext;
    if (!C) return;
    ac = new C();
    /* Mezcla común con compresión suave para conservar impacto sin saturar. */
    master = ac.createDynamicsCompressor();
    master.threshold.value = -18; master.knee.value = 12; master.ratio.value = 5;
    master.attack.value = 0.004; master.release.value = 0.16; master.connect(ac.destination);
    musicGain = ac.createGain(); musicGain.gain.value = 0.115; musicGain.connect(master);
    sfxGain = ac.createGain(); sfxGain.gain.value = 0.30; sfxGain.connect(master);
    musicAudio = new window.Audio('assets/rola2.m4a');
    musicAudio.loop = true;
    musicAudio.preload = 'auto';
    musicAudio.volume = 1;
    musicSource = ac.createMediaElementSource(musicAudio);
    musicSource.connect(musicGain);
  }
  function resume() { if (ac && ac.state === 'suspended') ac.resume(); }
  function tone(freq, dur, type = 'square', vol = 0.4, slide = 0, delay = 0) {
    if (!ac) return;
    const t0 = ac.currentTime + delay;
    const o = ac.createOscillator(), g = ac.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t0);
    if (slide) o.frequency.linearRampToValueAtTime(Math.max(30, freq + slide), t0 + dur);
    g.gain.setValueAtTime(vol, t0);
    g.gain.exponentialRampToValueAtTime(0.001, t0 + dur);
    o.connect(g); g.connect(sfxGain);
    o.start(t0); o.stop(t0 + dur + 0.02);
  }
  function noise(dur, vol = 0.3, freq = 1200, q = 1) {
    if (!ac) return;
    const len = Math.max(1, Math.floor(ac.sampleRate * dur));
    const buf = ac.createBuffer(1, len, ac.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 1.4);
    const src = ac.createBufferSource(); src.buffer = buf;
    const f = ac.createBiquadFilter(); f.type = 'bandpass'; f.frequency.value = freq; f.Q.value = q;
    const g = ac.createGain(); g.gain.value = vol;
    src.connect(f); f.connect(g); g.connect(sfxGain);
    src.start(); src.stop(ac.currentTime + dur + 0.02);
  }

  const sfx = {
    whiff: () => { noise(0.07, 0.10, 2600, 2); },
    light: () => { noise(0.06, 0.24, 1800, 1.4); tone(320, 0.05, 'square', 0.16, -120); },
    medium: () => { noise(0.09, 0.30, 1300, 1.2); tone(200, 0.08, 'square', 0.22, -90); },
    heavy: () => { noise(0.14, 0.42, 900, 1); tone(110, 0.16, 'square', 0.30, -50); },
    block: () => { tone(900, 0.05, 'triangle', 0.32); tone(1350, 0.04, 'triangle', 0.20); noise(0.05, 0.14, 3200, 2); },
    guardPush: () => { noise(0.12, 0.22, 2200, 1.6); tone(520, 0.10, 'sawtooth', 0.16, 240); },
    jump: () => { tone(360, 0.12, 'sine', 0.24, 260); },
    dash: () => { noise(0.14, 0.20, 900, 0.8); },
    launch: () => { tone(180, 0.28, 'sawtooth', 0.34, 420); noise(0.16, 0.24, 700, 1); },
    special: () => { tone(300, 0.22, 'square', 0.32, 420); noise(0.16, 0.20, 1500, 1); },
    fireball: () => { tone(520, 0.26, 'sawtooth', 0.26, -260); noise(0.22, 0.22, 1700, 1.2); },
    hyper: () => { for (let i = 0; i < 7; i++) tone(180 + i * 130, 0.20, 'square', 0.34, 140, i * 0.05); },
    superFlash: () => { tone(900, 0.5, 'sine', 0.3, -600); noise(0.4, 0.2, 900, 0.6); },
    tag: () => { tone(420, 0.10, 'square', 0.28, 200); tone(700, 0.12, 'square', 0.26, -180, 0.08); },
    assist: () => { tone(560, 0.09, 'square', 0.24); tone(760, 0.10, 'square', 0.22, 120, 0.07); },
    ko: () => { tone(300, 0.5, 'sawtooth', 0.42, -240); noise(0.45, 0.34, 800, 0.8); },
    menu: () => { tone(880, 0.05, 'square', 0.22); },
    select: () => { tone(660, 0.07, 'square', 0.26); tone(990, 0.08, 'square', 0.24, 0, 0.06); },
    round: () => { tone(440, 0.11, 'square', 0.3); tone(660, 0.11, 'square', 0.3, 0, 0.11); tone(880, 0.24, 'square', 0.34, 0, 0.22); },
    ok: () => { tone(600, 0.06, 'square', 0.24); tone(900, 0.10, 'square', 0.22, 0, 0.05); },
    denied: () => { tone(220, 0.16, 'sawtooth', 0.26, -80); },
  };

  /* Limita ráfagas repetidas de impactos, saltos y proyectiles. */
  const sfxLast = Object.create(null);
  const sfxGap = { whiff: 0.045, light: 0.055, medium: 0.065, heavy: 0.08, jump: 0.08, dash: 0.09, block: 0.06, fireball: 0.10 };
  for (const [name, fn] of Object.entries(sfx)) {
    sfx[name] = (...args) => {
      const now = ac?.currentTime ?? 0;
      if (now < (sfxLast[name] || 0)) return;
      sfxLast[name] = now + (sfxGap[name] || 0.025);
      fn(...args);
    };
  }
  /* Loop chiptune original (bajo + arpegio), respaldo sin pista externa. */
  const pattern = [
    [110, 0.24], [164, 0.24], [220, 0.24], [164, 0.24],
    [123, 0.24], [185, 0.24], [247, 0.24], [185, 0.24],
    [98, 0.24], [147, 0.24], [196, 0.24], [147, 0.24],
    [131, 0.24], [196, 0.24], [262, 0.24], [196, 0.24],
  ];
  let step = 0;
  function startMusic() {
    if (!ac) init();
    resume();
    if (musicAudio) {
      musicAudio.play().catch(() => {});
      return;
    }
    if (musicTimer) return;
    const tick = () => {
      const [f, d] = pattern[step % pattern.length];
      const t0 = ac.currentTime;
      const o = ac.createOscillator(), g = ac.createGain();
      o.type = 'triangle'; o.frequency.value = f;
      g.gain.setValueAtTime(0.30, t0); g.gain.exponentialRampToValueAtTime(0.001, t0 + d);
      o.connect(g); g.connect(musicGain); o.start(t0); o.stop(t0 + d);
      const o2 = ac.createOscillator(), g2 = ac.createGain();
      o2.type = 'square'; o2.frequency.value = f * 2;
      g2.gain.setValueAtTime(0.07, t0); g2.gain.exponentialRampToValueAtTime(0.001, t0 + d);
      o2.connect(g2); g2.connect(musicGain); o2.start(t0); o2.stop(t0 + d); step++;
    };
    tick(); musicTimer = setInterval(tick, 235);
  }
  function stopMusic() {
    if (musicAudio) musicAudio.pause();
    if (musicTimer) { clearInterval(musicTimer); musicTimer = null; }
  }
  function isMusicPlaying() { return musicAudio ? !musicAudio.paused : !!musicTimer; }
  return { init, resume, sfx, startMusic, stopMusic, isMusicPlaying, get ctx() { return ac; } };
})();

