/* --- Carga de sprites + generación de paletas alternativas. --- */
const Art = {
  base: {},       // bank -> [{img|canvas}]
  variants: {},   // charId -> {frames:[canvas|img], w, h}
  boss: null,
  boss1: null,
  boss2: null,
  total: 0, done: 0,

  load(onProgress) {
    const jobs = [];
    for (const [name, def] of Object.entries(BANKS)) {
      this.base[name] = def.frames.map((src) => new Promise((res) => {
        const im = new Image();
        im.onload = () => { this.total++; this.done++; onProgress?.(this.done / Math.max(1, this.total)); res(im); };
        im.onerror = () => { this.total++; this.done++; onProgress?.(this.done / Math.max(1, this.total)); res(null); };
        im.src = src;
      }));
    }
    const bossP = (src, key) => new Promise((res) => {
      const im = new Image();
      im.onload = () => { this.total++; this.done++; onProgress?.(this.done / Math.max(1, this.total)); this[key] = im; res(im); };
      im.onerror = () => { this.total++; this.done++; onProgress?.(this.done / Math.max(1, this.total)); this[key] = null; res(null); };
      im.src = src;
    });
    const boss1P = bossP(MIGUEL1_SRC, 'boss1');
    const boss2P = bossP(MIGUEL2_SRC, 'boss2');
    const baseJobs = Object.entries(this.base).map(async ([name, frames]) => {
      this.base[name] = (await Promise.all(frames)).filter(Boolean);
    });
    return Promise.all([...baseJobs, boss1P, boss2P]).then(() => this.buildVariants());
  },

  /* Recolorea únicamente la ropa: los píxeles cuya tonalidad cae dentro del
   * rango del banco se rotan a la tonalidad del personaje; la piel y el pelo
   * se conservan intactos. */
  recolor(img, ranges, hue) {
    const w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    const g = c.getContext('2d'); g.drawImage(img, 0, 0);
    let data;
    try { data = g.getImageData(0, 0, w, h); } catch (e) { return c; }
    const px = data.data;
    for (let i = 0; i < px.length; i += 4) {
      if (px[i + 3] < 10) continue;
      const r = px[i] / 255, gg = px[i + 1] / 255, b = px[i + 2] / 255;
      const mx = Math.max(r, gg, b), mn = Math.min(r, gg, b), d = mx - mn;
      if (d < 0.10) continue;
      let hh;
      if (mx === r) hh = ((gg - b) / d + 6) % 6; else if (mx === gg) hh = (b - r) / d + 2; else hh = (r - gg) / d + 4;
      hh /= 6;
      let inside = false;
      for (const [lo, hi] of ranges) {
        if (hi > 1) { if (hh >= lo || hh <= hi - 1) { inside = true; break; } }
        else if (hh >= lo && hh <= hi) { inside = true; break; }
      }
      if (!inside) continue;
      const s = mx === 0 ? 0 : d / mx, v = mx;
      let nr, ng, nb;
      const i6 = Math.floor(hue * 6), f = hue * 6 - i6;
      const p = v * (1 - s), q = v * (1 - f * s), t = v * (1 - (1 - f) * s);
      switch (i6 % 6) {
        case 0: nr = v; ng = t; nb = p; break;
        case 1: nr = q; ng = v; nb = p; break;
        case 2: nr = p; ng = v; nb = t; break;
        case 3: nr = p; ng = q; nb = v; break;
        case 4: nr = t; ng = p; nb = v; break;
        default: nr = v; ng = p; nb = q; break;
      }
      px[i] = nr * 255; px[i + 1] = ng * 255; px[i + 2] = nb * 255;
    }
    g.putImageData(data, 0, 0);
    return c;
  },

  buildVariants() {
    if (this.boss1) this.variants.miguel1 = { frames: [this.boss1], drawH: 430, feetPad: 8 };
    if (this.boss2) this.variants.miguel2 = { frames: [this.boss2], drawH: 500, feetPad: 10 };
    for (const [name, def] of Object.entries(BANKS)) {
      const key = name;
      this.base[key] = this.base[key].filter(Boolean);
    }
    for (const ch of ROSTER) {
      const def = BANKS[ch.bank];
      const src = this.base[ch.bank];
      /* No bloquear el arranque procesando millones de píxeles en un solo
       * turno. El banco original se usa como fallback visual; esto mantiene
       * todos los sprites disponibles y permite que el menú abra de inmediato. */
      const frames = src;
      this.variants[ch.id] = { frames, drawH: def.drawH, feetPad: def.feetPad, spriteFacesRight: def.spriteFacesRight };
    }
  },

  get(charId) { return this.variants[charId] || { frames: [], drawH: 300, feetPad: 0 }; },
  pose(charId, role) {
    const bank = CHAR[charId]?.bank || 'dc';
    const map = POSE[bank];
    const v = map[role];
    return Array.isArray(v) ? v : [v];
  },
};

