/* --- Asistencias: cada personaje ofrece tres tipos (alfa, beta, gamma). --- */
const ASSIST_TYPES = {
  a: { key: 'a', tag: 'PROYECTIL', desc: 'Ataca a distancia' },
  b: { key: 'b', tag: 'ANTI-AÉREO', desc: 'Cubre el aire' },
  g: { key: 'g', tag: 'LANZADOR', desc: 'Lanza al rival' },
};

function assistMove(bank, type) {
  const P = POSE[bank];
  const profile = { kato: 'dc', dcnormal: 'dc', dcazul: 'dc', dcrojo: 'dc', dcakuma: 'dc', crater: 'dc', wiznew: 'wizz', mistikwiz: 'wizz', wizznew: 'wizz', wmistiko: 'wizz', dcBlack: 'noir' }[bank] || bank;
  const tint = { dc: '#39a7ff', wizz: '#ff3b52', noir: '#6f5bff' }[profile];
  if (type === 'a') {
    return special({
      id: 'asProj', name: 'ASISTENCIA PROYECTIL', pose: P.assistP, startup: 12, active: 4, recovery: 26,
      damage: 10, hitstun: 18, blockstun: 12, hitstop: 5, meter: 3, color: tint, fx: 'orb',
      sfx: 'fireball', boxes: [], isAssist: true,
      proj: { vx: 8.4, w: 58, h: 48, y: -140, damage: 10, hitstun: 18, blockstun: 12, hitstop: 5, color: tint, life: 130, level: 'mid', pierce: 0 },
    });
  }
  if (type === 'b') {
    return special({
      id: 'asRise', name: 'ASISTENCIA ANTI-AÉREA', pose: P.launcherP, startup: 6, active: 10, recovery: 22,
      damage: 11, hitstun: 22, blockstun: 12, hitstop: 6, meter: 3, color: '#ffe14a', fx: 'rise',
      sfx: 'launch', isAssist: true, launch: -12.5, knockdown: true,
      boxes: [{ x: 36, y: -236, w: 100, h: 156 }],
      moveSelf: { vy: -11.5, vx: 2.0, onStart: true },
    });
  }
  return special({
    id: 'asLaunch', name: 'ASISTENCIA LANZADORA', pose: P.assistK, startup: 8, active: 5, recovery: 24,
    damage: 12, hitstun: 26, blockstun: 13, hitstop: 7, meter: 3, color: '#ffd21f', fx: 'launch',
    sfx: 'launch', isAssist: true, launch: -13.4, launcherFlag: true,
    boxes: [{ x: 44, y: -200, w: 108, h: 110 }],
    moveSelf: { vx: 4.0, onStart: true },
  });
}

