function movesFor(charId) {
  if (charId === 'miguel1') return MIGUEL1_MOVES;
  const bank = CHAR[charId].bank;
  return MOVES[bank] || MOVES[bank === 'dcnormal' ? 'dc' : 'noir'];
}
function assistsFor(charId) {
  /* Miguel 1 no puede atacar como asistente; sus movimientos son solo para el personaje activo. */
  if (charId === 'miguel1') return ['a', 'b', 'g'].map((key) => special({
    id: `miguel1NoAssist${key.toUpperCase()}`, name: 'SIN ASISTENCIA', pose: 0,
    startup: 1, active: 1, recovery: 1, damage: 0, boxes: [], meter: 0,
    color: '#ff1738', isAssist: true,
  }));
  return ['a', 'b', 'g'].map((t) => assistMove(MOVES[CHAR[charId].bank] ? CHAR[charId].bank : 'noir', t));
}

/* ======================= EFECTOS VISUALES =============================== */

const Particles = [];
const Afterimages = [];
const Floaters = [];

function spawnSpark(x, y, color, count = 12, power = 1) {
  for (let i = 0; i < count; i++) {
    Particles.push({
      type: 'spark', x, y, vx: rand(-7, 7) * power, vy: rand(-8, 2) * power,
      life: rand(0.22, 0.5), age: 0, size: rand(3, 8) * power, color, grav: 0.55,
      rot: rand(0, 6.28), spin: rand(-0.4, 0.4),
    });
  }
}
function spawnDust(x, y, dir = 0) {
  for (let i = 0; i < 7; i++) {
    Particles.push({
      type: 'dust', x: x + rand(-18, 18), y, vx: dir * rand(0.5, 3) + rand(-1.4, 1.4),
      vy: rand(-2.6, -0.6), life: rand(0.3, 0.62), age: 0, size: rand(5, 13),
      color: '#cdbda2', grav: 0.16,
    });
  }
}
function spawnRing(x, y, color, maxR = 110, life = 0.34) {
  Particles.push({ type: 'ring', x, y, r: 12, maxR, life, age: 0, color, lw: 6 });
}
function spawnTrail(x, y, color, count = 6) {
  for (let i = 0; i < count; i++) {
    Particles.push({
      type: 'trail', x: x - i * 14, y: y + rand(-24, 24), vx: rand(-2, 0),
      vy: rand(-0.6, 0.6), life: rand(0.18, 0.34), age: 0, size: rand(4, 11),
      color, grav: 0,
    });
  }
}
function spawnDashFx(f) {
  const travel = f.facing * f.dashDir;
  const color = f.char?.chroma || '#8fe6ff';
  spawnRing(f.x - travel * 26, f.y - 112, color, 86, 0.22);
  spawnDust(f.x - travel * 28, GROUND_Y, -travel);
  for (let i = 0; i < 14; i++) {
    Particles.push({ type: 'streak', x: f.x - travel * rand(10, 82), y: f.y - rand(42, 182),
      vx: -travel * rand(1.2, 3.8), vy: rand(-0.5, 0.5), life: rand(0.16, 0.3), age: 0,
      size: rand(2, 5), len: rand(18, 48), dir: travel, color, grav: 0 });
  }
  spawnSpark(f.x - travel * 44, f.y - 110, color, 12, 0.7);
}
function spawnDoubleJumpFx(f) {
  const color = f.char?.chroma2 || '#b8ff8f';
  spawnRing(f.x, f.y - 28, color, 118, 0.3);
  spawnDust(f.x, f.y + 8, f.facing);
  spawnSpark(f.x, f.y - 34, color, 18, 0.9);
  for (let i = 0; i < 10; i++) {
    Particles.push({ type: 'streak', x: f.x + rand(-30, 30), y: f.y + rand(-24, 12),
      vx: rand(-2.2, 2.2), vy: rand(0.8, 3.8), life: rand(0.18, 0.34), age: 0,
      size: rand(2, 4), len: rand(14, 32), dir: 1, color, grav: 0.08 });
  }
}
function spawnFloater(x, y, text, color, size = 34, life = 0.9) {
  Floaters.push({ x, y, text, color, size, life, age: 0 });
}
function pushAfterimage(f) {
  const art = Art.get(f.charId);
  const im = art.frames[f.currentPoseIndex()];
  if (!im) return;
  Afterimages.push({ img: im, x: f.x, y: f.y, facing: f.facing, charId: f.charId, life: 0.26, age: 0, alpha: 0.5 });
}

function updateFx(dt) {
  for (let i = Particles.length - 1; i >= 0; i--) {
    const p = Particles[i];
    p.age += dt;
    if (p.age >= p.life) { Particles.splice(i, 1); continue; }
    const fs = dt * 60;
    if (p.type !== 'ring') {
      p.x += p.vx * fs; p.y += p.vy * fs; p.vy += (p.grav || 0) * fs;
      p.vx *= Math.pow(0.96, fs);
    }
  }
  for (let i = Afterimages.length - 1; i >= 0; i--) {
    const a = Afterimages[i];
    a.age += dt;
    if (a.age >= a.life) Afterimages.splice(i, 1);
  }
  for (let i = Floaters.length - 1; i >= 0; i--) {
    const f = Floaters[i];
    f.age += dt; f.y -= 34 * dt;
    if (f.age >= f.life) Floaters.splice(i, 1);
  }
}

function resetFx() { Particles.length = 0; Afterimages.length = 0; Floaters.length = 0; }

/* ======================= LUCHADOR ====================================== */

const STATE = {
  IDLE: 'idle', WALK: 'walk', CROUCH: 'crouch', JUMP: 'jump', ATTACK: 'attack',
  HITSTUN: 'hitstun', BLOCKSTUN: 'blockstun', KNOCKDOWN: 'knockdown', GETUP: 'getup',
  DASH: 'dash', KO: 'ko', INTRO: 'intro', WIN: 'win', TAGIN: 'tagin', LEAVING: 'leaving',
  THROWN: 'thrown',
};

class Fighter {
  constructor(team, charId, index) {
    this.team = team;
    this.charId = charId;
    this.index = index;
    this.isAssist = false;
    this.maxHp = LIFE;
    this.hp = LIFE;
    this.redHp = 0;
    this.motion = new MotionBuffer();
    this.reset(0, 1);
  }

  reset(x, facing) {
    this.x = x; this.y = GROUND_Y;
    this.prevX = x; this.prevY = GROUND_Y;
    this.vx = 0; this.vy = 0;
    this.facing = facing;
    this.onGround = true;
    this.state = STATE.IDLE;
    this.stateFrame = 0;
    this.move = null;
    this.moveFrame = 0;
    this.sizeBoostTimer = 0;
    this.sizeDownTimer = 0;
    this.damageBoostTimer = 0;
    this.hitInstance = 0;
    this.hitArmed = true;
    this.hitList = new Set();
    this.blocking = false;
    this.blockingLow = false;
    this.invuln = 0;
    this.armor = 0;
    this.juggle = 0;
    this.airSpecialUsed = false;
    this.airChainUsed = new Set();
    this.chainUsed = new Set();
    this.comboHits = 0;
    this.walkTimer = 0;
    this.dashDir = 0;
    this.dashFrame = 0;
    this.flashTimer = 0;
    this.guardPushTimer = 0;
    this.guardHoldFrames = 0;
    this.guardBreakTimer = 0;
    this.lastTap = { left: -99, right: -99, up: -99, down: -99 };
    this.doubleJumpAvailable = true;
    this.specialEvadeTimer = 0;
    this.downTimer = 0;
    this.getupInvuln = 0;
    this.poseIndex = 0;
    this.assistCooldown = 0;
    this.ai = null;
  }

  get char() { return CHAR[this.charId]; }
  get moves() { return movesFor(this.charId); }
  get alive() { return this.hp > 0; }
  get isActive() { return this.team && this.team.active === this; }

  /* ---------- Consultas de estado ---------- */
  isAttacking() { return this.state === STATE.ATTACK; }
  isStunned() { return this.state === STATE.HITSTUN || this.state === STATE.BLOCKSTUN || this.state === STATE.THROWN; }
  isDown() { return this.state === STATE.KNOCKDOWN || this.state === STATE.GETUP; }
  canAct() {
    return this.state !== STATE.KO && this.state !== STATE.HITSTUN && this.state !== STATE.BLOCKSTUN
      && this.state !== STATE.KNOCKDOWN && this.state !== STATE.GETUP && this.state !== STATE.THROWN
      && this.state !== STATE.INTRO && this.state !== STATE.TAGIN && this.state !== STATE.WIN;
  }
  canMove() { return this.canAct() && this.state !== STATE.ATTACK; }
  hasHitConnected() { return this.hitList.size > 0; }

  /* ---------- Cajas ---------- */
  hurtboxes() {
    if (this.state === STATE.KNOCKDOWN || this.state === STATE.THROWN) {
      return [{ x: -70, y: -50, w: 140, h: 52 }];
    }
    if (this.state === STATE.CROUCH || (this.isAttacking() && this.move && this.move.crouching)) {
      return [{ x: -44, y: -132, w: 90, h: 132 }];
    }
    if (!this.onGround) return [{ x: -46, y: -178, w: 90, h: 160 }];
    if (this.isAttacking() && this.move && this.move.duckProfile) return [{ x: -44, y: -150, w: 90, h: 150 }];
    return [{ x: -46, y: -212, w: 92, h: 212 }];
  }

  activeBoxes() {
    if (!this.isAttacking() || !this.move) return [];
    const m = this.move;
    const t = this.moveFrame;
    if (t < m.startup || t >= m.startup + m.active) return [];
    return m.boxes || [];
  }

  /* ---------- Animación ---------- */
  currentPoseIndex() {
    const P = POSE[this.char.bank];
    const scalar = (role, fallback = 0) => {
      const v = P[role];
      return Array.isArray(v) ? v[0] : (v ?? fallback);
    };
    /* WIZ usa ilustraciones independientes, no un sprite-sheet. Alternamos
     * poses por tiempo para que el personaje no quede congelado en una sola. */
    const wiz = this.char.bank === 'wiznew';
    const normalWizz = this.char.bank === 'wizznew';
    const mystic = this.char.bank === 'wmistiko';
    const wizIdle = () => 0;
    const wizzIdle = () => [0, 0, 1, 0][Math.floor(this.stateFrame / 10) % 4];
    const mysticIdle = () => [0, 0, 5, 0][Math.floor(this.stateFrame / 12) % 4];
    const attackFrameSequence = (id) => {
      const key = String(id || '').toLowerCase();
      const button = /(?:^|[^a-z])(lp|mp|hp|lk|mk|hk)(?:$|[^a-z])/.exec(key)?.[1]
        || /(?:lp|mp|hp|lk|mk|hk)/.exec(key)?.[0];
      const byButton = {
        // Cada botón recorre tres poses distintas para que nunca parezca congelado.
        lp: [0, 1, 2], mp: [1, 2, 3], hp: [2, 3, 4],
        lk: [3, 4, 5], mk: [4, 5, 0], hk: [5, 0, 1],
      };
      if (/hy/.test(key)) return [6, 6, 6, 2];
      if (/sp|launcher|assist/.test(key)) return [2, 6, 5, 4];
      return byButton[button] || [0, 1, 0];
    };
    const wizzAttack = (m) => {
      const seq = attackFrameSequence(m?.id);
      return seq[Math.floor(this.moveFrame / 3) % seq.length];
    };
    const mysticAttack = (m) => {
      const id = String(m?.id || '').toLowerCase();
      const hyper = /hy/.test(id);
      const magic = /sp|launcher|assist/.test(id);
      const button = /(?:lp|mp|hp|lk|mk|hk)/.exec(id)?.[0];
      const byButton = {
        lp: [5, 0, 6, 1], mp: [0, 6, 1, 5], hp: [6, 1, 5, 0],
        lk: [2, 8, 3, 7], mk: [8, 3, 7, 2], hk: [3, 7, 2, 8],
      };
      const seq = hyper ? [1] : (magic ? [4, 6, 7, 3] : (byButton[button] || [5, 0, 6, 1]));
      return seq[Math.floor(this.moveFrame / 3) % seq.length];
    };
    const wizAttack = (m) => {
      const seq = attackFrameSequence(m?.id);
      return seq[Math.floor(this.moveFrame / 3) % seq.length];
    };
    switch (this.state) {
      case STATE.IDLE: return wiz ? wizIdle() : (normalWizz ? wizzIdle() : (mystic ? mysticIdle() : scalar('idle')));
      case STATE.WALK: return wiz ? [0, 2, 0, 1][Math.floor(this.walkTimer * 8) % 4] : (normalWizz ? [0, 1, 0, 1][Math.floor(this.walkTimer * 8) % 4] : (mystic ? [0, 5, 0, 5][Math.floor(this.walkTimer * 8) % 4] : (Array.isArray(P.walk) ? P.walk[Math.floor(this.walkTimer * 7) % P.walk.length] : P.walk)));
      case STATE.CROUCH: return scalar('crouch');
      case STATE.JUMP: return scalar(this.vy < 0 ? 'jump' : 'fall');
      case STATE.DASH: return scalar(this.dashDir > 0 ? 'dashF' : 'dashB');
      case STATE.BLOCKSTUN: return scalar(this.onGround ? (this.blockingLow ? 'blockLow' : 'block') : 'blockAir');
      case STATE.HITSTUN: return scalar(this.onGround ? (this.blockingLow ? 'hitLow' : 'hit') : 'hitAir');
      case STATE.KNOCKDOWN: return scalar('down');
      case STATE.GETUP: return scalar('getUp');
      case STATE.THROWN: return scalar('down');
      case STATE.KO: return scalar('down');
      case STATE.TAGIN: return scalar('assistP');
      case STATE.INTRO: return wiz ? 2 : (normalWizz ? 0 : (mystic ? 0 : scalar('idle')));
      case STATE.WIN: return scalar('win');
      case STATE.ATTACK: {
        const m = this.move;
        if (!m) return wiz ? wizIdle() : (normalWizz ? wizzIdle() : (mystic ? mysticIdle() : scalar('idle')));
        if (wiz) return wizAttack(m);
        if (normalWizz) return wizzAttack(m);
        if (mystic) return mysticAttack(m);
        const pose = typeof m.pose === 'number' ? m.pose : P[m.pose];
        if (pose === undefined) return scalar('idle');
        // Los bancos tradicionales tienen una pose por golpe. Animamos la entrada,
        // el impacto y la salida usando el idle como transición; así cada botón
        // produce movimiento visible aunque el banco no tenga una tira de frames.
        const idle = scalar('idle');
        const id = String(m?.id || '').toLowerCase();
        const button = /(?:lp|mp|hp|lk|mk|hk)/.exec(id)?.[0];
        const buttonIndex = { lp: 0, mp: 1, hp: 2, lk: 3, mk: 4, hk: 5 }[button] ?? 0;
        const stance = id.startsWith('c') ? 'c' : (id.startsWith('j') ? 'j' : 's');
        const frameCount = Math.max(1, Art.get(this.charId).frames.length);
        // Cada botón recibe una entrada y una salida diferentes, incluso cuando
        // la tabla POSE comparte el mismo frame de impacto (cLP/cLK, jMP/jMK, etc.).
        // El desplazamiento depende de postura y botón, y siempre queda dentro
        // del banco real del personaje.
        const stanceOffset = stance === 'c' ? 2 : (stance === 'j' ? 4 : 0);
        let entryPose = (buttonIndex + stanceOffset) % frameCount;
        let exitPose = (buttonIndex + stanceOffset + 2) % frameCount;
        if (entryPose === pose) entryPose = (entryPose + 1) % frameCount;
        if (exitPose === pose || exitPose === entryPose) exitPose = (exitPose + 1) % frameCount;
        if (frameCount === 1) return pose;
        const seq = [entryPose, pose, exitPose, entryPose];
        return seq[Math.floor(this.moveFrame / 3) % seq.length];
      }
      default: return wiz ? wizIdle() : (normalWizz ? wizzIdle() : (mystic ? mysticIdle() : scalar('idle')));
    }
  }

  /* ---------- Ciclo principal ---------- */
  update(world, input) {
    this.prevX = this.x;
    this.prevY = this.y;
    const rival = this.opponent();
    if (rival && rival.alive && Math.abs(rival.x-this.x)>1) this.facing = rival.x >= this.x ? 1 : -1;
    this.assistCooldown = Math.max(0, this.assistCooldown - 1);
    this.invuln = Math.max(0, this.invuln - 1);
    this.armor = Math.max(0, this.armor - 1);
    this.flashTimer = Math.max(0, this.flashTimer - 1);
    this.guardPushTimer = Math.max(0, this.guardPushTimer - 1);
    this.guardBreakTimer = Math.max(0, this.guardBreakTimer - 1);
    this.getupInvuln = Math.max(0, this.getupInvuln - 1);
    this.specialEvadeTimer = Math.max(0, this.specialEvadeTimer - 1);
    this.sizeBoostTimer = Math.max(0, this.sizeBoostTimer - 1);
    this.sizeDownTimer = Math.max(0, this.sizeDownTimer - 1);
    this.damageBoostTimer = Math.max(0, this.damageBoostTimer - 1);
    this.stateFrame++;

    if (input) {
      const facing = this.opponentFacing();
      this.facing = facing;
      this.motion.push(this.dirRelative(input, facing), facing);
      if (input.tapDir.down) this.lastTap.down = world.frame;
      this.wantSuperJump = !!(input.tapDir.up || input.dir.up);
      if (this.comboResetTimer > 0) this.comboResetTimer--;
      else this.comboHits = 0;
    }

    if (this.state === STATE.KO) { this.updatePhysics(world); this.koFall(); return; }
    if (this.state === STATE.INTRO || this.state === STATE.WIN || this.state === STATE.TAGIN) {
      this.updatePhysics(world);
      return;
    }
    if (this.state === STATE.KNOCKDOWN) {
      this.downTimer++;
      this.vx *= 0.86;
      this.updatePhysics(world);
      if (this.downTimer > 34) { this.state = STATE.GETUP; this.stateFrame = 0; this.getupInvuln = 14; this.downTimer = 0; }
      return;
    }
    if (this.state === STATE.GETUP) {
      this.updatePhysics(world);
      if (this.stateFrame > 12) { this.state = STATE.IDLE; this.stateFrame = 0; }
      return;
    }
    if (this.state === STATE.HITSTUN || this.state === STATE.THROWN) {
      this.vx *= Math.pow(0.9, 1);
      if (!this.onGround) this.vx *= Math.pow(0.985, 1);
      this.updatePhysics(world);
      if (this.stateFrame > this.stunFrames && (this.onGround || this.hitstunAirOK)) {
        if (this.onGround) {
          this.state = STATE.IDLE; this.stateFrame = 0; this.juggle = 0;
          this.comboHits = 0; this.comboResetTimer = 0;
        }
      }
      return;
    }
    if (this.state === STATE.BLOCKSTUN) {
      this.vx *= 0.88;
      this.updatePhysics(world);
      if (input && input.btn && this.pressCount(input) >= 2 && this.guardPushTimer <= 0) this.advancingGuard(world);
      if (this.stateFrame > this.stunFrames) { this.state = STATE.IDLE; this.stateFrame = 0; this.blocking = false; this.blockingLow = false; }
      return;
    }

    /* --- Estado accionable --- */
    if (this.state === STATE.ATTACK) {
      if (this.move?.mobileSpecial && input) {
        const d = input.dir || {};
        const direction = Number(!!d.right) - Number(!!d.left);
        if (this.onGround && input.tapDir?.up) {
          this.vy = PHYS.jumpVy;
          this.onGround = false;
          this.resetAirActions();
          Audio.sfx.jump();
        }
        if (direction) this.vx = direction * 6.2;
        else if (this.onGround) this.vx = 0;
        this.updateAttack(world);
      } else if (input && this.tryCancel(world, input)) { /* encadena inmediatamente */ }
      else this.updateAttack(world);
    } else if (!input) {
      /* sin entrada (actores de asistencia) */
    } else {
      this.updateFree(world, input);
    }
    if (this.isBoss && world.bossId === 'miguel2' && this.state !== STATE.ATTACK) this.vx *= 0.55;
    this.updatePhysics(world);
  }

  dirRelative(input, facing) {
    const d = input.dir;
    const fwd = facing === 1 ? d.right : d.left;
    const back = facing === 1 ? d.left : d.right;
    return { left: back, right: fwd, up: d.up, down: d.down };
  }
  opponentFacing() {
    const o = this.opponent();
    if (!o) return this.facing;
    return o.x >= this.x ? 1 : -1;
  }
  opponent() {
    const w = this.team && this.team.world;
    if (!w) return null;
    const other = this.team === w.teams[1] ? w.teams[2] : w.teams[1];
    return other.active || other.members.find((m) => m.alive && m !== this) || null;
  }
  pressCount(input) {
    let n = 0;
    for (const b of BTN) if (input.btn[b]) n++;
    return n;
  }

  /* ---------- Movimiento libre, bloqueo, dash, super salto ---------- */
  updateFree(world, input) {
    const d = input.dir;
    const facing = this.facing;
    const fwd = facing === 1 ? d.right : d.left;
    const back = facing === 1 ? d.left : d.right;
    const atk = this.pressCount(input);
    const tapA = input.tap.lp || input.tap.mp || input.tap.hp || input.tap.lk || input.tap.mk || input.tap.hk;
    const wantHyper = atk >= 2;

    /* --- definición del movimiento a ejecutar --- */
    const pick = this.chooseMove(input, world);
    if (pick) { this.chainUsed.clear(); this.airChainUsed.clear(); this.startMove(world, pick); return; }

    /* Atrás ya no bloquea automáticamente: permite caminar libremente hacia
     * cualquier lado. El bloqueo queda reservado para la acción explícita. */
    /* Guardia universal: atrás + abajo = guardia baja agachada; atrás sola = guardia alta. */
    this.blocking = false;
    this.blockingLow = false;
    if (!this.team?.isCPU && this.onGround && back && !tapA && !wantHyper) {
      this.blocking = true;
      this.blockingLow = !!d.down;
      this.guardHoldFrames++;
      this.vx = 0;
      this.setFreeState(this.blockingLow ? STATE.CROUCH : STATE.IDLE);
      if (this.guardHoldFrames >= 180) { // 3 segundos de guardia continua
        this.guardHoldFrames = 0;
        this.guardBreakTimer = 120; // 2 segundos inconsciente
        this.state = STATE.HITSTUN;
        this.stateFrame = 0;
        this.stunFrames = 120;
        this.hitstunAirOK = true;
        this.move = null;
        this.vx = 0;
        this.vy = 0;
        this.blocking = false;
        this.blockingLow = false;
        Audio.sfx.hit();
        return;
      }
      return;
    }
    this.guardHoldFrames = 0;

    /* --- super salto: abajo y luego arriba dentro de la ventana --- */
    if (this.onGround && input.tapDir.up && this.lastTap.down !== undefined && world.frame - this.lastTap.down <= PHYS.superJumpWindow) {
      this.superJump(true);
      return;
    }
    if (this.onGround && input.tapDir.up) {
      this.vy = PHYS.jumpVy; this.onGround = false;
      this.state = STATE.JUMP; this.stateFrame = 0;
      this.resetAirActions();
      this.lastTap.up = world.frame;
      Audio.sfx.jump();
      spawnDust(this.x, GROUND_Y);
      if (fwd) this.vx = (facing === 1 ? 1 : -1) * PHYS.walkF * 0.85;
      if (back) this.vx = (facing === 1 ? -1 : 1) * PHYS.walkB * 0.85;
      if (!fwd && !back) this.vx = this.facing * PHYS.jumpForward;
      return;
    }

    /* --- dash por doble toque --- */
    if (input.tapDir.right || input.tapDir.left) {
      const dir = input.tapDir.right ? 1 : -1;
      /* `facing` apunta al rival: 1 = derecha, -1 = izquierda. */
      const fwdTap = dir === facing;
      const key = dir === 1 ? 'right' : 'left';
      if (world.frame - (this.lastTap[key] ?? -99) <= PHYS.doubleTapWindow) {
        this.lastTap[key] = -99;
        this.startDash(fwdTap ? 1 : -1);
        return;
      }
      this.lastTap[key] = world.frame;
    }

    /* --- desplazamiento básico --- */
    if (this.onGround) {
      if (d.down) { this.vx = 0; this.setFreeState(STATE.CROUCH); }
      else if (d.left !== d.right) {
        /* Conservamos el sentido físico del teclado y elegimos la velocidad
         * según sea avance hacia el rival o retroceso desde cualquier lado. */
        const physicalDir = d.left ? -1 : 1;
        const movingForward = physicalDir === facing;
        this.vx = physicalDir * (movingForward ? PHYS.walkF : PHYS.walkB);
        this.setFreeState(STATE.WALK);
        this.walkTimer += STEP;
      } else { this.vx = 0; this.setFreeState(STATE.IDLE); this.walkTimer += STEP; }
    } else {
      /* control aéreo */
      /* ↓ ↑ ↑: el segundo arriba extiende el super salto con una
         trayectoria larga dirigida automáticamente hacia el oponente. */
      if (input.tapDir.up && this.superJumping && !this.superJumpExtended
        && world.frame - this.lastTap.up <= PHYS.doubleJumpWindow) {
        this.extendSuperJump(world);
        this.lastTap.up = -99;
        return;
      }
      if (input.tapDir.up && this.doubleJumpAvailable
        && world.frame - this.lastTap.up <= PHYS.doubleJumpWindow) {
        this.doubleJump();
        this.lastTap.up = -99;
        return;
      }
      if (d.left) this.vx = Math.max(this.vx - PHYS.airDrift, -PHYS.walkF * 1.1);
      if (d.right) this.vx = Math.min(this.vx + PHYS.airDrift, PHYS.walkF * 1.1);
      if (this.state !== STATE.ATTACK) this.state = STATE.JUMP;
    }
  }

  setFreeState(s) { if (this.state !== s) { this.state = s; this.stateFrame = 0; } }

  resetAirActions() {
    this.airSpecialUsed = false;
    this.airChainUsed.clear();
    this.juggle = 0;
    this.doubleJumpAvailable = true;
  }

  chooseMove(input, world) {
    const m = this.moves;
    /* Miguel1: LP/A lanza el rayo original; atrás+botón y arriba+botón son ataques separados. */
    if (this.charId === 'miguel1') {
      const d = input.dir || {};
      const tap = input.tap || {};
      const backHeld = this.facing === 1 ? d.left : d.right;
      const anyButtonTap = tap.lp || tap.mp || tap.hp || tap.lk || tap.mk || tap.hk;
      if (d.up && anyButtonTap) return { id: 'miguelCan' };
      if (backHeld && anyButtonTap) return { id: 'miguelAttack' };
      if (tap.lp) return { id: 'miguelRay' };
      return null;
    }
    /* Comandos inyectados por la IA (evita simular la línea de tiempo). */
    if (input._motion) {
      const map = {
        qcf: 'spProj', qcfK: 'spRush', qcbK: 'spSpin', dpP: 'spRise', qcbP: 'spGrab',
        qcfPP: 'hyBeam', qcbKK: 'hyRush', doubleQcfP: 'hyUlt', chargeP: 'spCharge',
      };
      const id = map[input._motion];
      if (id && m[id]) return { id };
    }
    const d = input.dir;
    const tap = input.tap;
    const onGround = this.onGround;
    const atkCount = this.pressCount(input);
    const mb = this.motion;
    const facing = this.facing;
    const team = this.team;
    const freshQcf = mb.qcf() && mb.recent(6);
    const freshQcb = mb.qcb() && mb.recent(6);
    const freshDp = mb.dp() && mb.recent(6);

    /* --- hiper combos (prioridad) --- */
    if (team && team.gauge >= SUPER_LEVEL) {
      /* Acceso simplificado por joystick: adelante + HP/R1.
       * HP activa el hiper de energía y R1/HK el hiper de avance. */
      const forwardHeld = facing === 1 ? d.right : d.left;
      if (onGround && forwardHeld && tap.hp && m.hyBeam) { mb.clear(); return { id: 'hyBeam' }; }
      if (onGround && forwardHeld && tap.hk && m.hyRush) { mb.clear(); return { id: 'hyRush' }; }
      if (atkCount >= 2 && mb.doubleQcf() && team.gauge >= (m.hyUlt?.cost || 3) * SUPER_LEVEL) return { id: 'hyUlt' };
      if ((tap.lp && tap.mp) || (tap.mp && tap.hp)) {
        if (mb.qcf() || mb.match([2, 3, 6], 26)) { mb.clear(); return { id: 'hyBeam' }; }
      }
      if ((tap.lk && tap.mk) || (tap.mk && tap.hk)) {
        if (mb.qcb() || mb.match([2, 1, 4], 26)) { mb.clear(); return { id: 'hyRush' }; }
      }

    }

    /* --- especiales --- */
    const pTap = tap.lp || tap.mp || tap.hp;
    const kTap = tap.lk || tap.mk || tap.hk;
    if (onGround) {
      /* Proyectiles directos: un toque de joystick arriba/abajo + cualquier botón.
       * El buffer breve de abajo permite pulsar dirección y botón consecutivamente;
       * después del buffer, mantener abajo vuelve a dejar disponibles cLP/cMP/cHP/
       * cLK/cMK/cHK. */
      const anyAttackTap = pTap || kTap;
      const downProjectile = d.down && anyAttackTap
        && (input.tapDir.down || world.frame - this.lastTap.down <= 12);
      if (d.up && anyAttackTap) { mb.clear(); return { id: 'spProjUp' }; }
      if (downProjectile) { mb.clear(); return { id: 'spProj' }; }
      if (kTap && freshQcf) { mb.clear(); return { id: 'spRush' }; }
      if (pTap && freshDp) { mb.clear(); return { id: 'spRise' }; }
      if (kTap && freshQcb) { mb.clear(); return { id: 'spSpin' }; }
      if (pTap && freshQcb) { mb.clear(); return { id: 'spGrab' }; }
      if (pTap && mb.chargeBackOK() && mb.recent(4)) { mb.consumeChargeBack(); return { id: 'spCharge' }; }
    } else if (!this.onGround) {
      if (kTap && mb.qcb() && !this.airSpecialUsed) return { id: 'spDive' };
      if (kTap && mb.qcf() && !this.airSpecialUsed) return { id: 'spRush' };
    }

    /* --- normales (serie mágica) --- */
    const btns = ['lp', 'mp', 'hp', 'lk', 'mk', 'hk'];
    for (const b of btns) {
      if (!tap[b]) continue;
      const prefix = onGround ? (d.down ? 'c' : 's') : 'j';
      let id = prefix + b.toUpperCase();
      if (!this.moves[id]) id = 's' + b.toUpperCase();
      if (prefix === 'c' && b === 'hp') id = 'cHP';
      if (prefix === 'c' && b === 'hk') id = 'cHK';
      if (!onGround && !this.moves[id]) id = 'j' + b.toUpperCase();
      return { id };
    }
    return null;
  }

  startDash(dir) {
    this.state = STATE.DASH;
    this.stateFrame = 0;
    this.dashDir = dir;
    this.dashFrame = 0;
    const sgn = this.facing * (dir > 0 ? 1 : -1);
    this.x = clamp(this.x + sgn * DASH_SPACES * SPACE_PX, WALL_L, WALL_R);
    this.vx = 0;
    this.invuln = 0;
    Audio.sfx.dash();
    pushAfterimage(this);
    spawnDashFx(this);
  }

  startMove(world, entry, keepChain) {
    const source = this.moves[entry.id];
    if (!source) return;
    /* Ritmo arcade rápido: todos los botones responden antes y recuperan antes.
     * Se conserva el active original para no desalinear las hitboxes. */
    const m = Object.assign({}, source, {
      startup: Math.max(1, Math.round(source.startup * 0.86)),
      recovery: Math.max(2, Math.round(source.recovery * 0.84)),
    });
    if (m.type === 'hyper') {
      const cost = m.cost || 1;
      if (!this.team || this.team.gauge < cost * SUPER_LEVEL) return;
      this.team.gauge -= cost * SUPER_LEVEL;
      this.team.lastHyperAttacker = this;
      world.beginSuperFlash(this, m);
    }
    if (m.type === 'special') {
      Audio.sfx.special();
      this.specialEvadeTimer = 120;
    }
    this.state = STATE.ATTACK;
    this.stateFrame = 0;
    this.move = m;
    this.moveFrame = 0;
    this.hitInstance = 0;
    this.hitArmed = true;
    this.hitList.clear();
    if (!keepChain) { this.chainUsed.clear(); this.airChainUsed.clear(); }
    if (!this.onGround) this.airSpecialUsed = m.type === 'special' || m.type === 'hyper';
    if (m.sizeBoostFrames) this.sizeBoostTimer = Math.max(this.sizeBoostTimer, m.sizeBoostFrames);
    if (m.sizeDownFrames) this.sizeDownTimer = Math.max(this.sizeDownTimer, m.sizeDownFrames);
    if (m.damageBoostFrames) this.damageBoostTimer = Math.max(this.damageBoostTimer, m.damageBoostFrames);
    if (m.freezeSelf) { this.vx = 0; this.vy = 0; }
    if (m.moveSelf && m.moveSelf.onStart) {
      if (m.moveSelf.vx) this.vx = this.facing * m.moveSelf.vx;
      if (m.moveSelf.vy) { this.vy = m.moveSelf.vy; this.onGround = false; }
    }
    if (m.invuln) this.invuln = m.invuln;
    if (m.armor) this.armor = 12;
    if (m.type === 'special' || m.type === 'hyper') pushAfterimage(this);
  }

  /* ---------- Cancelaciones: serie mágica y encadenado a especiales ---------- */
  tryCancel(world, input) {
    const m = this.move;
    if (!m || !input || !input.tap) return false;
    const t = this.moveFrame;
    if (t < m.startup) return false;
    const connected = this.hitList.size > 0;
    const team = this.team;
    const isNormal = m.type === 'normal';
    const inAir = !this.onGround;
    const pTap = input.tap.lp || input.tap.mp || input.tap.hp;
    const kTap = input.tap.lk || input.tap.mk || input.tap.hk;

    /* 1) Cancelación a hiper combo (solo si el golpe conectó o la ventana se abrió) */
    if (team && team.gauge >= SUPER_LEVEL) {
      if ((input.tap.lp && input.tap.mp) || (input.tap.mp && input.tap.hp)) {
        if (this.motion.qcf() || this.motion.match([2, 3, 6], 26)) {
          this.motion.clear();
          this.startMove(world, { id: 'hyBeam' }, true);
          return true;
        }
      }
      if ((input.tap.lk && input.tap.mk) || (input.tap.mk && input.tap.hk)) {
        if (this.motion.qcb() || this.motion.match([2, 1, 4], 26)) {
          this.motion.clear();
          this.startMove(world, { id: 'hyRush' }, true);
          return true;
        }
      }
      if (input.tap.hp && input.tap.mp && this.motion.doubleQcf()
        && team.gauge >= (this.moves.hyUlt?.cost || 3) * SUPER_LEVEL) {
        this.motion.clear();
        this.startMove(world, { id: 'hyUlt' }, true);
        return true;
      }
    }
    /* 2) Cancelación a especial: exige que el normal haya conectado o bloqueado */
    if (isNormal && connected) {
      if (kTap && this.motion.qcf()) { this.motion.clear(); this.startMove(world, { id: 'spRush' }, true); return true; }
      if (pTap && this.motion.dp())  { this.motion.clear(); this.startMove(world, { id: 'spRise' }, true); return true; }
      if (kTap && this.motion.qcb()) { this.motion.clear(); this.startMove(world, { id: 'spSpin' }, true); return true; }
      if (pTap && this.motion.qcb()) { this.motion.clear(); this.startMove(world, { id: 'spGrab' }, true); return true; }
    }
    /* 3) Serie mágica: solo a normales de mayor jerarquía, una vez por cadena */
    if (isNormal) {
      for (const b of ['lp', 'mp', 'hp', 'lk', 'mk', 'hk']) {
        if (!input.tap[b]) continue;
        const id = (inAir ? 'j' : (input.dir && input.dir.down ? 'c' : 's')) + b.toUpperCase();
        const nm = this.moves[id];
        if (!nm) continue;
        const used = inAir ? this.airChainUsed : this.chainUsed;
        if (nm.chain > m.chain && !used.has(id)) {
          used.add(id);
          this.startMove(world, { id }, true);
          return true;
        }
      }
    }
    return false;
  }

  /* ---------- Avance del ataque en curso ---------- */
  updateAttack(world) {
    const m = this.move;
    this.moveFrame++;
    if (m.proj && this.moveFrame === m.startup && !m.isAssistActor) {
      world.spawnProjectile(this, m.proj, m);
    }
    const total = m.startup + m.active + m.recovery;
    if (m.kind === 'launcher' && this.moveFrame > m.startup && this.moveFrame < m.startup + m.active + 4) {
      /* launcher cancela a super salto si el jugador mantiene arriba */
      if (this.wantSuperJump) {
        this.state = STATE.JUMP;
        this.move = null; this.hitList.clear();
        this.superJump(true);
        return;
      }
    }
    if (this.moveFrame >= total) {
      this.move = null;
      this.state = this.onGround ? STATE.IDLE : STATE.JUMP;
      this.stateFrame = 0;
    }
  }

  superJump(pursue) {
    this.vy = PHYS.superJumpVy; this.onGround = false;
    this.state = STATE.JUMP; this.stateFrame = 0;
    this.resetAirActions();
    this.superJumping = true;
    this.superJumpExtended = false;
    this.lastTap.up = WORLD ? WORLD.frame : this.lastTap.up;
    Audio.sfx.jump();
    spawnDust(this.x, GROUND_Y);
    spawnRing(this.x, GROUND_Y - 30, '#8fe6ff', 120, 0.4);
  }

  extendSuperJump(world) {
    const foe = this.opponent();
    const toward = foe ? (foe.x >= this.x ? 1 : -1) : this.facing;
    this.superJumpExtended = true;
    this.doubleJumpAvailable = false;
    this.superJumping = true;
    this.vx = toward * PHYS.superJumpForward;
    this.vy = Math.min(this.vy, PHYS.superJumpExtendVy);
    this.state = STATE.JUMP;
    this.stateFrame = 0;
    Audio.sfx.jump();
    spawnDoubleJumpFx(this);
    spawnRing(this.x, this.y - 30, '#ffd21f', 145, 0.42);
  }

  doubleJump() {
    this.doubleJumpAvailable = false;
    this.vy = PHYS.doubleJumpVy;
    this.onGround = false;
    this.state = STATE.JUMP;
    this.stateFrame = 0;
    this.superJumping = false;
    this.vx = this.facing * PHYS.doubleJumpForward;
    Audio.sfx.jump();
    spawnDoubleJumpFx(this);
  }

  /* ---------- Física ---------- */
  updatePhysics(world) {
    const hoveringMiguel2 = this.isBoss && this.charId === 'miguel2' && this.alive && this.state !== STATE.KO;
    if (hoveringMiguel2) {
      /* Vuelo suave y estable: nunca cae ni toca la línea del piso. */
      this.vy = 0;
      this.y = GROUND_Y - 220;
      this.onGround = false;
      if (this.state === STATE.DASH) this.vx *= 0.94;
      else if (this.state !== STATE.WALK) this.vx *= PHYS.friction;
      this.vx = clamp(this.vx, -18, 18);
      this.x += this.vx;
      this.x = clamp(this.x, WALL_L, WALL_R);
      return;
    }
    const g = this.superJumping && this.vy < 0 ? PHYS.gravity * PHYS.superJumpFloat : PHYS.gravity;
    if (!this.onGround) {
      this.vy = Math.min(PHYS.maxFall, this.vy + g);
      if (this.state === STATE.DASH) this.vx *= 0.94;
    } else if (this.state === STATE.DASH) {
      this.vx = this.vx * 0.94 + sign(this.vx) * 0.02;
    } else if (this.state !== STATE.WALK) {
      this.vx *= PHYS.friction;
      if (Math.abs(this.vx) < 0.1) this.vx = 0;
    }
    if (this.state === STATE.DASH) {
      this.dashFrame++;
      if (this.dashFrame % 3 === 0) pushAfterimage(this);
      if (this.dashFrame > PHYS.dashFrames) { this.state = this.onGround ? STATE.IDLE : STATE.JUMP; this.stateFrame = 0; }
    }
    this.vx = clamp(this.vx, -18, 18);
    this.x += this.vx;
    this.y += this.vy;
    if (this.y >= GROUND_Y) {
      if (!this.onGround) {
        spawnDust(this.x, GROUND_Y, sign(this.vx));
        if (this.state === STATE.HITSTUN || this.state === STATE.THROWN) {
          this.onGround = true; this.y = GROUND_Y; this.vy = 0; this.vx = 0;
          this.setKnockdown();
          return;
        }
        if (this.hardLand) { this.hardLand = false; this.setKnockdown(); }
      }
      this.y = GROUND_Y; this.vy = 0; this.onGround = true;
      this.superJumping = false;
      this.superJumpExtended = false;
      if (this.state === STATE.JUMP) { this.state = STATE.IDLE; this.stateFrame = 0; this.resetAirActions(); }
    } else {
      this.onGround = false;
    }
    if (this.x <= WALL_L && this.vx < 0) this.vx = 0;
    if (this.x >= WALL_R && this.vx > 0) this.vx = 0;
    this.x = clamp(this.x, WALL_L, WALL_R);
  }

  setKnockdown() {
    this.state = STATE.KNOCKDOWN;
    this.stateFrame = 0;
    this.downTimer = 0;
    this.move = null;
    this.juggle = 0;
    this.blocking = false;
  }

  koFall() {
    this.vx *= 0.9;
    if (this.y >= GROUND_Y) { this.y = GROUND_Y; this.vy = 0; this.onGround = true; }
    else this.vy = Math.min(PHYS.maxFall, this.vy + PHYS.gravity);
    this.x += this.vx; this.y += this.vy;
    this.x = clamp(this.x, WALL_L, WALL_R);
  }

  /* ---------- Reacción a impactos ---------- */
  takeHit(hit, attacker, hitPoint) {
    if (!this.alive || this.state === STATE.KO) return false;

    /* Bloqueo correcto */
    if (!hit.unblockable && this.checkBlock(hit)) return this.blockHit(hit, attacker, hitPoint);

    /* Armadura: absorbe un golpe sin interrumpir */
    if (this.armor > 0 && hit.hitstop < 9) {
      spawnSpark(hitPoint.x, hitPoint.y, '#ffe14a', 10, 0.8);
      Audio.sfx.block();
      return true;
    }

    const scale = this.comboScaling();
    const resistance = this.isBoss && this.charId === 'miguel2' && hit.kind !== 'proj' ? 0.10 : 1;
    const damageBoost = attacker?.damageBoostTimer > 0 ? 1.15 : 1;
    /* Los impactos porcentuales son exactos y no se reducen por combo. */
    const dmg = hit.percentMaxHp
      ? this.maxHp * hit.percentMaxHp * damageBoost
      : Math.max(hit.kind === 'proj' ? 1 : 0.2, hit.damage * scale * resistance * damageBoost);
    this.hp = Math.max(0, this.hp - dmg);
    this.redHp = Math.min(this.maxHp - this.hp, this.redHp + dmg * 0.55);
    if (this.team) this.team.gauge = Math.min(MAX_SUPER_LEVELS * SUPER_LEVEL, this.team.gauge + dmg * 1.5);

    /* Feedback de impacto: parpadeo rojo breve y retroceso suave.
       Se aplica también a proyectiles porque ambos pasan por takeHit(). */
    this.flashTimer = 8;
    this.blocking = false;
    this.move = null;
    this.hitList.clear();

    const launched = hit.launch || hit.launcherFlag;
    const wasAir = !this.onGround;
    this.state = STATE.HITSTUN;
    this.stateFrame = 0;
    this.stunFrames = hit.hitstun;
    this.hitstunAirOK = true;
    this.vx = attacker ? attacker.facing * Math.max(3.2, (hit.pushHit || 3) * 1.2) : 0;
    if (launched) {
      this.onGround = false;
      this.vy = typeof hit.launch === 'number' ? hit.launch : -10.5;
      this.juggle++;
    } else if (wasAir) {
      this.onGround = false;
      if (this.vy >= 0) this.vy = -2.2;
    } else if (hit.knockdown) {
      this.onGround = false;
      this.vy = -2.8;
    }

    this.x = clamp(this.x + this.vx * 0.45, WALL_L, WALL_R);

    if (hit.knockdown && !launched) { this.hardLand = true; }
    if (hit.airEnder && !this.onGround) { this.state = STATE.THROWN; this.vx = attacker ? attacker.facing * 16 : 0; this.vy = -6; }

    if (this.hp <= 0) {
      this.state = STATE.KO;
      this.stateFrame = 0;
      this.vx = attacker ? attacker.facing * 7 : 0;
      this.vy = -7;
      this.onGround = false;
      Audio.sfx.ko();
    }
    return true;
  }

  comboScaling() {
    const n = this.comboHits || 0;
    return clamp(1 - n * 0.075, 0.28, 1);
  }

  checkBlock(hit) {
    if (hit.unblockable || hit.level === 'throw') return false;
    if (!this.onGround) {
      return this.blocking && hit.level !== 'low';
    }
    if (!this.blocking) return false;
    if (hit.level === 'low') return this.blockingLow;
    if (hit.level === 'overhead') return !this.blockingLow;
    return true;
  }

  blockHit(hit, attacker, hitPoint) {
    const chip = hit.damage * (hit.unblockable ? 0 : hit.level === 'mid' ? 0.06 : 0.09);
    this.hp = Math.max(1, this.hp - chip);
    this.state = STATE.BLOCKSTUN;
    this.stateFrame = 0;
    this.stunFrames = hit.blockstun;
    this.vx = attacker ? -attacker.facing * (hit.pushBlock || 4) : 0;
    if (attacker) attacker.vx = attacker.facing * (hit.pushBlock || 4) * 0.55;
    if (this.team) this.team.gauge = Math.min(MAX_SUPER_LEVELS * SUPER_LEVEL, this.team.gauge + chip * 2.4);
    if (attacker && attacker.team) attacker.team.gauge = Math.min(MAX_SUPER_LEVELS * SUPER_LEVEL, attacker.team.gauge + chip * 1.2);
    Audio.sfx.block();
    spawnSpark(hitPoint.x, hitPoint.y, '#9fe9ff', 9, 0.85);
    spawnRing(hitPoint.x, hitPoint.y, '#7fd6ff', 66, 0.22);
    return true;
  }

  advancingGuard(world) {
    this.guardPushTimer = 24;
    const o = this.opponent();
    this.stateFrame = Math.max(0, this.stateFrame - 6);
    if (o) {
      o.vx = (o.x >= this.x ? 1 : -1) * 7.2;
      o.x = clamp(o.x + o.vx * 1.2, WALL_L, WALL_R);
      spawnDust(o.x, GROUND_Y, sign(o.vx));
    }
    Audio.sfx.guardPush();
    spawnRing(this.x, this.y - 110, '#8fe6ff', 90, 0.28);
  }

  /* ---------- Dibujo ---------- */
  draw(g) {
    const art = Art.get(this.charId);
    if (!art.frames.length) return;
    const idx = clamp(this.currentPoseIndex(), 0, art.frames.length - 1);
    const poseImage = art.frames[idx];
    const moveArt = this.charId === 'miguel1' && this.state === STATE.ATTACK
      && this.move?.id === 'miguelAttack' && Miguel1MoveArt.attack.complete
      && Miguel1MoveArt.attack.naturalWidth > 0 ? Miguel1MoveArt.attack : null;
    const im = moveArt || poseImage;
    if (!im) return;
    const natW = im.naturalWidth || im.width;
    const natH = im.naturalHeight || im.height;
    const h = FIGHTER_DRAW_HEIGHT;
    const w = natW * (h / natH);

    /* La dirección lógica siempre apunta al oponente: 1 = derecha, -1 = izquierda.
     * Los bancos crater/wero fueron dibujados mirando a la izquierda; los demás
     * bancos miran a la derecha. La inversión depende solo de facing, no del
     * lado del equipo, para que la IA también mire correctamente al rival. */
    /* CRATER y WERO necesitaban invertirse para mirar al oponente.
     * El resto conserva exactamente su orientación anterior. */
    /* Cada banco declara su orientación original. Los nuevos personajes
     * fueron preparados mirando a la derecha; se invierten únicamente cuando
     * el rival está a la izquierda. WIZZ conserva su excepción histórica. */
    const spriteFacesRight = art.spriteFacesRight ?? true;
    const baseFlip = spriteFacesRight ? this.facing === -1 : this.facing === 1;
    const flip = baseFlip;

    /* sombra */
    const shadowScale = this.onGround ? 1 : clamp(1 - (GROUND_Y - this.y) / 900, 0.4, 1);
    g.save();
    g.globalAlpha = 0.42 * shadowScale;
    g.fillStyle = '#000';
    g.beginPath();
    g.ellipse(this.x, GROUND_Y + 6, 62 * shadowScale, 12 * shadowScale, 0, 0, Math.PI * 2);
    g.fill();
    g.restore();
    if (this.blocking || this.state === STATE.BLOCKSTUN) {
      g.save();
      const low = this.blockingLow || this.currentPoseIndex() === (POSE[this.char.bank]?.blockLow);
      g.globalAlpha = this.state === STATE.BLOCKSTUN ? 0.42 : 0.25;
      g.strokeStyle = low ? '#73d8ff' : '#b9f3ff';
      g.fillStyle = low ? 'rgba(34,150,243,.12)' : 'rgba(121,229,255,.10)';
      g.lineWidth = 7; g.shadowColor = '#39d9ff'; g.shadowBlur = 22;
      g.beginPath(); g.ellipse(this.x + this.facing * 22, this.y - (low ? 92 : 125), low ? 78 : 92, low ? 68 : 112, 0, 0, Math.PI * 2); g.fill(); g.stroke();
      g.restore();
    }
    g.save();
    g.translate(this.x, this.y + (art.feetPad || 0));
    if (flip) g.scale(-1, 1);
    let filter = '';
    if (this.guardBreakTimer > 0 && (this.guardBreakTimer % 10) < 5) filter += 'brightness(1.75) saturate(2.8) sepia(1) hue-rotate(300deg) drop-shadow(0 0 18px #ff1738) ';
    else if (this.flashTimer > 0 && (this.flashTimer % 4) < 2) filter += 'brightness(1.8) saturate(3.2) sepia(1) hue-rotate(300deg) drop-shadow(0 0 16px #ff1738) ';
    if (this.invuln > 0) g.globalAlpha *= 0.72;
    if (this.state === STATE.ATTACK && this.move && (this.move.type === 'hyper')) filter += `drop-shadow(0 0 18px ${this.move.color}) `;
    if (filter) g.filter = filter;
    const spriteScale = this.sizeDownTimer > 0 ? 0.7 : (this.sizeBoostTimer > 0 ? 1.25 : 1);
    g.drawImage(im, -w * spriteScale / 2, -h * spriteScale, w * spriteScale, h * spriteScale);
    g.filter = 'none';
    g.restore();
  }

  drawBoxes() { /* depuración: se activa con la tecla de depuración */ }
}

/* ======================= HURTBOX / WORLD HELPERS ======================== */

function fighterHurtboxes(f) {
  return f.hurtboxes().map((b) => worldBox(b, f));
}

/* ======================= PROYECTILES =================================== */

/* Proyectiles: color ligado al personaje que los dispara. */
const PROJ_COLOR = {
  blue: '#168cff', yellow: '#ffd21f', red: '#ff2b3d', black: '#0b0b0f', white: '#f7fbff',
};
const PROJ_GROUP_OF = {
  /* DC y DCAKUMA: azul */
  dc: 'blue', refresh: 'blue', dcb: 'blue', dcakuma: 'blue',
  /* WIZZ: rojo */
  wz: 'red', mistikwiz: 'red', wzm: 'red',
  /* MIGUEL: negro */
  miguel1: 'black', miguel2: 'black', miguelnew: 'black',
  /* El resto queda en amarillo salvo los proyectiles especiales blancos. */
  crater: 'yellow', dcr: 'yellow', manuelin: 'yellow', noir: 'yellow',
  yiyo: 'yellow', toto: 'yellow', wero: 'yellow', random: 'yellow', aron: 'yellow', victor: 'yellow', dandy: 'yellow',
};
function projColorFor(charId) { return PROJ_COLOR[PROJ_GROUP_OF[charId]] || PROJ_COLOR.yellow; }
function isMulticolorProjectile(charId) { return charId === 'crater'; }
const PROJ_SIZE = 2.64;
const PROJ_COST = SUPER_LEVEL / 2;
const RAIN_COST = SUPER_LEVEL;

class Projectile {
  constructor(owner, spec, move) {
    this.owner = owner;
    this.team = owner.team;
    this.facing = owner.facing;
    this.x = owner.x + owner.facing * 62;
    this.prevX = this.x;
    this.y = owner.y + spec.y;
    this.vx = (spec.vx || 0) * owner.facing;
    this.vy = spec.vy || 0; this.vertical = !!spec.vertical;
    this.w = spec.w * PROJ_SIZE; this.h = spec.h * PROJ_SIZE;
    this.renderW = (spec.renderW || spec.w) * PROJ_SIZE;
    this.renderH = (spec.renderH || spec.h) * PROJ_SIZE;
    this.artKey = owner?.charId === 'wero' ? 'weroProjectile' : (owner?.charId === 'toto' ? 'miguel1' : (spec.art || null));
    this.artYOffset = spec.artYOffset || 0;
    this.dmg = spec.damage; this.percentMaxHp = spec.percentMaxHp || 0; this.unblockable = !!spec.unblockable;
    this.hitstun = spec.hitstun; this.blockstun = spec.blockstun;
    this.hitstop = spec.hitstop;
    this.multiColor = isMulticolorProjectile(owner.char?.id);
    this.color = projColorFor(owner.char?.id) || spec.color;
    this.level = spec.level;
    this.life = spec.life; this.pierce = spec.pierce || 0;
    this.age = 0;
    this.reflectCooldown = 0;
    this.dead = false;
    this.trailT = 0;
  }
  box() { return { x: this.x - this.w / 2, y: this.y - this.h / 2, w: this.w, h: this.h }; }
  update() {
    this.prevX = this.x;
    this.x += this.vx; this.y += this.vy;
    this.age++;
    this.reflectCooldown = Math.max(0, this.reflectCooldown - 1);
    this.trailT++;
    if (this.trailT % 2 === 0) {
      Particles.push({ type: 'trail', x: this.x, y: this.y + rand(-10, 10), vx: rand(-1.6, 0), vy: rand(-0.5, 0.5), life: 0.22, age: 0, size: rand(5, 12), color: this.color, grav: 0 });
    }
    if (this.age > this.life || this.x < -80 || this.x > VW + 80 || this.y < -120 || this.y > VH + 120) this.dead = true;
  }
  draw(g) {
    const customArt = this.artKey ? ProjectileArt[this.artKey] : null;
    if (customArt?.complete && customArt.naturalWidth > 0) {
      const scale = Math.min(this.renderW / customArt.naturalWidth, this.renderH / customArt.naturalHeight);
      const w = customArt.naturalWidth * scale, h = customArt.naturalHeight * scale;
      g.save();
      g.translate(this.x, this.y + this.artYOffset);
      if (this.facing < 0 && this.artKey !== 'miguel1Can') g.scale(-1, 1);
      g.drawImage(customArt, -w / 2, -h / 2, w, h);
      g.restore();
      return;
    }
    const bottle = this.owner?.charId === 'miguel1' && this.artKey !== 'miguel1Can' ? ProjectileArt.miguel1 : null;
    if (bottle?.complete && bottle.naturalWidth > 0) {
      const natW = bottle.naturalWidth, natH = bottle.naturalHeight;
      const scale = Math.min(this.w / natW, this.h / natH);
      const w = natW * scale, h = natH * scale;
      g.save();
      g.translate(this.x, this.y);
      g.shadowColor = '#ff8a35'; g.shadowBlur = 12;
      g.drawImage(bottle, -w / 2, -h / 2, w, h);
      g.restore();
      return;
    }
    g.save();
    g.globalCompositeOperation = 'lighter';
    g.shadowColor = this.multiColor ? '#ff6a2a' : this.color; g.shadowBlur = 26;
    if (this.multiColor) {
      const rainbow = g.createLinearGradient(-this.w * 0.55, 0, this.w * 0.55, 0);
      rainbow.addColorStop(0, '#ff1744');
      rainbow.addColorStop(0.2, '#ffea00');
      rainbow.addColorStop(0.4, '#35e875');
      rainbow.addColorStop(0.6, '#20d9ff');
      rainbow.addColorStop(0.8, '#8b5cff');
      rainbow.addColorStop(1, '#ff2bd6');
      g.fillStyle = rainbow;
    } else {
      g.fillStyle = this.color;
    }
    g.translate(this.x, this.y);
    const visualW = this.w;
    const visualH = this.h;
    if (this.vertical) {
      g.beginPath(); g.rect(-visualW*.24, -visualH*.5, visualW*.48, visualH); g.fill();
    } else {
      g.rotate(Math.atan2(this.vy, this.vx || this.facing));
      g.beginPath(); g.ellipse(0, 0, visualW*.42, visualH*.42, 0, 0, Math.PI*2); g.fill();
    }
    g.globalAlpha=0.9; g.fillStyle=this.vertical?'#8fc8ff':'#fff'; g.beginPath();
    g.ellipse(0, 0, this.vertical?visualW*.12:visualW*.2, this.vertical?visualH*.28:visualH*.2, 0, 0, Math.PI*2); g.fill();
    g.restore();
  }
}

/* ======================= EQUIPO (2v2) ================================== */

class Team {
  constructor(world, side, picks, opts = {}) {
    this.world = world;
    this.side = side;              // 1 | 2
    this.isCPU = !!opts.isCPU;
    this.picks = picks;
    this.members = picks.map((p, i) => new Fighter(this, p.charId, i));
    this.assistType = [];
    this.activeIndex = 0;
    this.gauge = opts.gauge || 0;
    this.tagCooldown = 0;
    this.calledAssist = false;
    this.assistActor = null;
    this.snapLocked = [false, false];
    this.combo = { hits: 0, damage: 0, timer: 0, label: '' };
    this.lastHyperAttacker = null;
    this.superFlashMove = null;
  }
  get active() { return this.members[this.activeIndex]; }
  get partnerIndex() { return this.activeIndex === 0 ? 1 : 0; }
  get partner() { return null; }
  get aliveMembers() { return this.members.filter((m) => m.alive); }
  get defeated() { return this.members.every((m) => !m.alive); }
  canDuo() { return false; }

  reset(x, facing) {
    this.activeIndex = 0;
    this.members.forEach((m) => { m.reset(x, facing); m.redHp = 0; });
    this.tagCooldown = 0;
    this.assistActor = null;
    this.calledAssist = false;
    this.combo = { hits: 0, damage: 0, timer: 0, label: '' };
  }

  update(input) {
    const w = this.world;
    this.tagCooldown = Math.max(0, this.tagCooldown - 1);

    /* En 1v1 no hay compañero en reserva ni actor de asistencia. */
    const active = this.active;
    if (active) active.update(w, input);

    /* Combo del equipo */
    if (this.combo.timer > 0) {
      this.combo.timer--;
      if (this.combo.timer === 0) this.combo.hits = 0;
    }
  }

  requestAssist(type, fromHyper) {
    const w = this.world;
    if (w.hitstop > 0) return false;
    if (this.assistActor || this.calledAssist) return false;
    const idx = this.partnerIndex;
    if (!this.partner.alive || this.snapLocked[idx]) return false;
    if (this.tagCooldown > 0) return false;
    const move = assistMove(CHAR[this.partner.charId].bank, this.assistType[idx]);
    const dir = this.active.facing;
    const a = new Fighter(this, this.partner.charId, idx);
    a.isAssist = true;
    a.maxHp = this.partner.maxHp;
    a.hp = this.partner.hp;
    a.redHp = this.partner.redHp;
    a.x = clamp(this.active.x - dir * 130, WALL_L, WALL_R);
    a.y = GROUND_Y;
    a.facing = dir;
    a.onGround = true;
    a.state = STATE.ATTACK;
    a.move = move;
    a.moveFrame = 0;
    a.invuln = 0;
    a.life = move.startup + move.active + move.recovery + 26;
    a.superJumping = false;
    this.assistActor = a;
    this.calledAssist = true;
    this.tagCooldown = fromHyper ? 8 : 26;
    Audio.sfx.assist();
    spawnDust(a.x, GROUND_Y, dir);
    return true;
  }

  requestTag() {
    const w = this.world;
    if (w.hitstop > 0) return false;
    if (this.tagCooldown > 0 || this.assistActor) return false;
    const idx = this.partnerIndex;
    if (!this.partner.alive || this.snapLocked[idx]) return false;
    const out = this.active, inc = this.partner;
    /* el que sale limpia su vida roja al volver */
    this.active.x = clamp(out.x, WALL_L, WALL_R);
    inc.x = out.x + out.facing * 18;
    inc.y = GROUND_Y;
    inc.facing = out.facing;
    inc.onGround = true;
    inc.state = STATE.TAGIN;
    inc.stateFrame = 0;
    inc.invuln = 16;
    inc.vx = 0; inc.vy = 0;
    inc.move = null;
    inc.hitList.clear();
    inc.comboHits = 0;
    this.activeIndex = idx;
    out.state = STATE.LEAVING;
    out.move = null;
    out.invuln = 10;
    /* ataque de relevo: golpe cruzado */
    const m = this.world.tagAttackMove(inc);
    out.vx = -out.facing * 4;
    this.tagCooldown = 70;
    Audio.sfx.tag();
    spawnRing(inc.x, GROUND_Y - 60, inc.char.chroma, 150, 0.4);
    spawnSpark(inc.x, GROUND_Y - 140, inc.char.chroma, 18, 1.1);
    /* golpe inmediato del que entra */
    this.world.applyCrossOver(inc, m);
    return true;
  }

  snapBack() {
    if (this.gauge < SUPER_LEVEL) return false;
    const w = this.world;
    const foe = w.teams[this.side === 1 ? 2 : 1];
    if (!foe || foe.members.filter((m) => m.alive).length < 2) return false;
    if (this.tagCooldown > 0) return false;
    this.gauge -= SUPER_LEVEL;
    this.tagCooldown = 60;
    Audio.sfx.tag();
    const target = foe.active;
    const incoming = foe.partner;
    foe.snapLocked[foe.activeIndex] = true;
    incoming.x = target.x; incoming.y = GROUND_Y; incoming.facing = target.facing;
    incoming.state = STATE.TAGIN; incoming.stateFrame = 0; incoming.invuln = 10;
    foe.activeIndex = foe.partnerIndex;
    target.state = STATE.HITSTUN; target.stunFrames = 30; target.vx = -this.active.facing * 9; target.vy = -7;
    target.onGround = false; target.redHp = 0; target.hp = Math.max(1, target.hp - 6);
    spawnFloater(target.x, target.y - 260, 'SNAP BACK!', '#ffd21f', 30, 1.1);
    return true;
  }
}

/* ======================= IA DEL CPU ==================================== */

class AiController {
  constructor(fighter, difficulty) {
    this.f = fighter;
    this.diff = difficulty;      // 0 = inmóvil, 0.7 .. 1.6
    this.plan = 'wait';
    this.timer = 0;
    this.hold = {};
    this.reaction = 0;
    this.lastMove = '';
    this.bag = [];
  }

  think(world) {
    const f = this.f;
    const out = {
      dir: { left: false, right: false, up: false, down: false },
      btn: { lp: false, mp: false, hp: false, lk: false, mk: false, hk: false, assistA: false, assistB: false, start: false },
      tap: { lp: false, mp: false, hp: false, lk: false, mk: false, hk: false, assistA: false, assistB: false, start: false },
      tapDir: { left: false, right: false, up: false, down: false },
      _ai: true,
    };
    if ((!f.isBoss || world.bossId !== 'miguel2') && (this.diff <= 0 || !f.alive)) return out;
    const foe = world.aiTargetOf(f);
    if (!foe || !foe.alive) return out;

    const dx = foe.x - f.x;
    if (f.isBoss && world.bossId === 'miguel2') {
      this.timer -= STEP;
      if (this.timer <= 0 && f.canAct()) {
        const dist=Math.abs(dx), q=Math.random();
        const helperDiff = f.team.helperAiDiff ?? 0.85;
        const helperAssistChance = clamp(0.18 * helperDiff, 0.02, 0.18);
        this.plan=dist>210?'approach':(q<.48?'bossStrike':(q<.76?'bossDash':'bossRay'));
        this.timer=rand(.28,.62)/clamp(this.diff,0.5,2);
      }
      const toward=dx>=0?'right':'left';
      if(this.plan==='approach'){out.dir[toward]=true;return out;}
      if(this.plan==='bossDash'){out.tapDir[toward]=true;out.dir[toward]=true;this.plan='wait';return out;}
      if(this.plan==='bossStrike'){const b=Math.random()<.5?'hp':'hk';out.btn[b]=true;out.tap[b]=true;this.plan='wait';return out;}
      if(this.plan==='bossRay') this.plan='wait';
    }
    const adist = Math.abs(dx);
    const toward = dx >= 0 ? 'right' : 'left';
    const away = dx >= 0 ? 'left' : 'right';
    const team = f.team;
    const gaugeReady = team.gauge >= SUPER_LEVEL;
    const ultReady = team.gauge >= SUPER_LEVEL * (team.active?.moves?.hyUlt?.cost || 3);

    /* La IA nunca se cubre: siempre debe recibir los ataques del jugador.
       No se genera ningún plan de bloqueo, ni siquiera como reacción. */
    if (this.plan === 'block') this.plan = 'wait';
    /* Anti-aéreo */
    if (!foe.onGround && foe.y < GROUND_Y - 130 && adist < 150 && Math.random() < 0.10 * this.diff) {
      this.plan = 'antiair'; this.timer = 0.2;
    }

    this.reaction = Math.max(0, this.reaction - STEP);
    this.timer -= STEP;

    if (this.timer <= 0 && this.plan !== 'block') {
      const r = Math.random();
      if (adist > 320) {
        if (gaugeReady && r < 0.18) this.plan = 'fireball';
        else if (r < 0.25) this.plan = 'special';
        else this.plan = 'approach';
      } else if (adist > 170) {
        if (ultReady && r < 0.10) this.plan = 'ult';
        else if (gaugeReady && r < 0.24) this.plan = 'hyper';
        else if (r < 0.42) this.plan = 'special';
        else if (r < 0.55) this.plan = 'dash';
        else this.plan = 'approach';
      } else {
        if (!this.bag.length) {
          const pool = ['lp', 'mp', 'hp', 'lk', 'mk', 'hk', 'cHP', 'cHK', 'lp', 'lk', 'throw'];
          for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
          if (pool[0] === this.lastMove) [pool[0], pool[1]] = [pool[1], pool[0]];
          this.bag = pool;
        }
        this.plan = this.bag.shift();
        this.lastMove = this.plan;
      }
      this.timer = rand(0.22, 0.5) / clamp(this.diff, 0.5, 2);
    }

    const press = (b) => { out.btn[b] = true; out.tap[b] = true; };
    const holdDir = (d) => { out.dir[d] = true; };

    switch (this.plan) {
      case 'block': this.plan = 'wait'; break; // bloqueo desactivado para la IA
      case 'approach': holdDir(toward); break;
      case 'retreat': holdDir(away); break;
      case 'fireball':
        out._motion = 'qcf'; press('lp'); this.plan = 'wait'; this.timer = 0.4; break;
      case 'special':
        out._motion = Math.random() < 0.5 ? 'qcfK' : 'qcbK'; press(Math.random() < 0.5 ? 'lk' : 'mk');
        this.plan = 'wait'; this.timer = 0.5; break;
      case 'antiair':
        out._motion = 'dpP'; press('hp'); this.plan = 'wait'; this.timer = 0.5; break;
      case 'hyper':
        out._motion = 'qcfPP'; press('lp'); press('hp'); this.plan = 'wait'; this.timer = 0.7; break;
      case 'ult':
        out._motion = 'doubleQcfP'; press('hp'); press('mp'); this.plan = 'wait'; this.timer = 0.9; break;
      case 'dash':
        out.tapDir[toward] = true; out.dir[toward] = true; this.plan = 'wait'; this.timer = 0.3; break;
      case 'jump': holdDir('up'); this.plan = 'wait'; break;
      case 'assist': case 'tag': this.plan = 'wait'; this.timer = 0.4; break;
      case 'throw':
        out._motion = 'qcbP'; press('mp'); this.plan = 'wait'; this.timer = 0.5; break;
      case 'lp': case 'mp': case 'hp': case 'lk': case 'mk': case 'hk':
        press(this.plan); this.plan = 'wait'; this.timer = 0.16; break;
      case 'cHP': holdDir('down'); press('hp'); this.plan = 'wait'; this.timer = 0.3; break;
      case 'cHK': holdDir('down'); press('hk'); this.plan = 'wait'; this.timer = 0.3; break;
      default: break;
    }
    return out;
  }

  /* Inyecta el comando especial directamente en la memoria de movimientos. */
  applyMotion() { }
}

/* ======================= MUNDO DE COMBATE ============================== */

let WORLD = null;

class World {
  constructor(mode, picks1, picks2, opts = {}) {
    this.mode = mode;
    this.frame = 0;
    this.hitstop = 0;
    this.shake = 0;
    this.timer = opts.timer ?? 99;
    this.timerMax = this.timer;
    this.over = false;
    this.winner = 0;
    this.result = null;
    this.superFlash = null;
    this.projectiles = [];
    this.announce_text = null;
    this.announceTimer = 0;
    this.bossBeam = null;
    this.bossBeamUsed = false;
    this.bossRayCooldown = 0;
    this.bossCharge = null;
    this.paused = false;
    this.teams = {
      1: new Team(this, 1, picks1, { isCPU: !!opts.cpu1, gauge: MAX_SUPER_LEVELS * SUPER_LEVEL }),
      2: new Team(this, 2, picks2, { isCPU: !!opts.cpu2, gauge: opts.gauge2 || 0 }),
    };
    this.teams[1].reset(360, 1);
    this.teams[2].reset(920, -1);
    this.teams[2].ai = null;
    this.boss = opts.boss || null;
    this.bossId = opts.bossId || 'miguel1';
    this.finalStage = !!opts.finalStage;
    this.hazardTimer = 0;
    if (this.boss) this.setupBoss();
    WORLD = this;
  }

  /* Trampas verticales de la arena final: daño porcentual, no bloqueables. */
  spawnHazard() {
    const owner = { team: null, x: 0, y: 0, facing: 1, charId: 'hazard', char: { id: 'hazard' } };
    this.projectiles.push(new Projectile(owner, {
      vx: 0, vy: 10, w: 40, h: 40, y: 0, damage: 0, percentMaxHp: 0.45, unblockable: true,
      hitstun: 16, blockstun: 0, hitstop: 4, color: '#7fe9ff', life: 80, level: 'overhead', pierce: 0,
    }, { id: 'hazard' }));
    const p = this.projectiles[this.projectiles.length - 1];
    p.x = rand(50, 280); p.prevX = p.x; p.y = -60; p.vx = 0; p.vy = 10; p.hazard = true;
  }

  setupBoss() {
    /* Miguel, jefe final grande: en 1v1 no hay ayudante ni personaje de reserva. */
    const t = this.teams[2];
    const f = t.members[0];
    f.charId = this.bossId;
    f.isBoss = true;
    f.maxHp = this.bossId === 'miguel1' ? 280 : 460;
    f.hp = f.maxHp;
    f.isBoss = true;
    t.helperAiDiff = 0;
    this.timer = this.bossId === 'miguel2' ? 24 : 20;
    this.timerMax = this.timer;
    if (this.bossId === 'miguel1') this.bossCharge = { frames: 0, required: 360, delay: 90, buttons: 'HP + HK' };
    if (this.bossId === 'miguel2') {
      /* Miguel 2 permanece suspendido; el rayo requiere una carga larga. */
      this.bossCharge = { frames: 0, required: 300, delay: 150, buttons: 'RAYO' };
    }
    f.x = 940;
    if (this.bossId === 'miguel2') {
      f.y = GROUND_Y - 220;
      f.prevY = f.y;
      f.onGround = false;
      f.vy = 0;
    }
    if (this.bossId !== 'miguel2') this.announce(`MIGUEL 1 · JEFE FINAL · ${this.timer} SEGUNDOS`, 2.4);
  }

  aiTargetOf(f) {
    const foe = f.team === this.teams[1] ? this.teams[2] : this.teams[1];
    return foe.assistActor || foe.active;
  }

  tagAttackMove(f) {
    return {
      id: 'tagAtk', name: 'CROSSOVER', type: 'special', kind: 'command',
      pose: 'assistP', startup: 2, active: 5, recovery: 14,
      boxes: [{ x: 40, y: -196, w: 118, h: 110 }], damage: 9, level: 'mid',
      hitstun: 20, blockstun: 12, hitstop: 7, pushHit: 3.0, pushBlock: 4.4,
      meter: 4, color: f.char.chroma, fx: 'dash', sfx: 'medium',
    };
  }

  applyCrossOver(f, move) {
    f.move = move;
    f.moveFrame = 0;
    f.state = STATE.TAGIN;
    f.stateFrame = 0;
    f.hitList.clear();
    f.pendingTagHit = true;
    Audio.sfx.medium();
    pushAfterimage(f);
  }

  announce(text, seconds = 1.4, style = 'normal') {
    this.announce_text = text;
    this.announceTimer = seconds * 60;
    this.announceStyle = style;
  }

  beginSuperFlash(fighter, move) {
    this.superFlash = { frames: move.flash || 22, total: move.flash || 22, fighter, move };
    Audio.sfx.superFlash();
    spawnRing(fighter.x, fighter.y - 120, move.color, 320, 0.6);
    spawnSpark(fighter.x, fighter.y - 130, move.color, 40, 1.6);
    this.shake = Math.max(this.shake, 10);
  }

  spawnProjectile(owner, spec, move) {
    this.projectiles.push(new Projectile(owner, spec, move));
    Audio.sfx.fireball();
  }

  /* ---------------- Resolución de golpes ---------------- */
  resolveHits() {
    for (const side of [1, 2]) {
      const atkTeam = this.teams[side];
      const defTeam = this.teams[side === 1 ? 2 : 1];
      const attackers = [atkTeam.active, atkTeam.assistActor].filter((a) => a && a.alive);
      const defenders = [defTeam.active, defTeam.assistActor].filter((d) => d && d.alive);
      for (const a of attackers) {
        if (!a.move) continue;
        this.resolveFighterHits(a, defTeam, defenders);
      }
    }
    /* proyectiles */
    for (const pr of this.projectiles) {
      const defTeam = pr.team === this.teams[1] ? this.teams[2] : this.teams[1];
      const defenders = [defTeam.active, defTeam.assistActor].filter((d) => d && d.alive);
      const current = pr.box();
      const previous = { x: pr.prevX - pr.w / 2, y: pr.y - pr.h / 2, w: pr.w, h: pr.h };
      const pbox = { x: Math.min(current.x, previous.x), y: Math.min(current.y, previous.y),
        w: Math.max(current.x + current.w, previous.x + previous.w) - Math.min(current.x, previous.x),
        h: Math.max(current.y + current.h, previous.y + previous.h) - Math.min(current.y, previous.y) };
      for (const d of defenders) {
        if (d.invuln > 0) continue;
        const hurt = fighterHurtboxes(d);
        if (hurt.some((h) => overlap(pbox, h))) {
          const point = { x: pr.x, y: pr.y };
          if (this.bossBeam && d === this.teams[2].members[0] && pr.owner.team === this.teams[1]) {
            this.bossBeam.shots = (this.bossBeam.shots || 0) + 1;
            pr.dead = true;
            spawnSpark(d.x, d.y - 180, '#39a7ff', 24, 1.5);
            spawnFloater(d.x, d.y - 260, `${this.bossBeam.shots}/3`, '#8fe6ff', 24, 0.8);
            if (this.bossBeam.shots >= 3) {
              this.bossBeam = null;
              d.state = STATE.IDLE;
              this.announce('RAYO CANCELADO', 1.2);
              Audio.sfx.hyper();
            }
            break;
          }
          /* Reflejo: mantener atrás justo antes del impacto devuelve el proyectil
             hacia el atacante. La guardia normal sigue funcionando para los golpes. */
          if (d.blocking && d.onGround && pr.reflectCooldown <= 0 && !pr.unblockable) {
            const originalOwner = pr.owner;
            const direction = originalOwner && d.x >= originalOwner.x ? -1 : 1;
            pr.owner = d;
            pr.team = d.team;
            pr.facing = direction;
            pr.vx = Math.max(5.5, Math.abs(pr.vx)) * direction;
            pr.x = clamp(d.x + pr.vx * 8, WALL_L, WALL_R);
            pr.y = d.y - 135;
            pr.reflectCooldown = 12;
            pr.multiColor = isMulticolorProjectile(d.char?.id);
            pr.color = projColorFor(d.char?.id) || pr.color;
            spawnSpark(point.x, point.y, '#ffe14a', 18, 1.15);
            spawnRing(point.x, point.y, '#ffe14a', 82, 0.3);
            Audio.sfx.guardPush();
            break;
          }

          const hit = {
            damage: pr.dmg, percentMaxHp: pr.percentMaxHp, unblockable: pr.unblockable,
            hitstun: pr.hitstun, blockstun: pr.blockstun, hitstop: pr.hitstop,
            level: pr.level, pushHit: 2.6, pushBlock: 3.6, color: pr.color, kind: 'proj',
          };
          const res = this.applyHit(d, pr.owner, hit, point, pr.color);
          if (res) {
            if (pr.pierce > 0) pr.pierce--;
            else pr.dead = true;
            break;
          }
        }
      }
    }
    this.projectiles = this.projectiles.filter((p) => !p.dead);
  }

  resolveFighterHits(a, defTeam, defenders) {
    const m = a.move;
    const boxes = a.activeBoxes();
    if (!boxes.length) return;
    /* multigolpe: rearma el golpe cada `hitGap` */
    if (m.hits > 1) {
      const t = a.moveFrame - m.startup;
      if (t >= (a.hitInstance + 1) * m.hitGap) {
        a.hitInstance++;
        a.hitList.clear();
      }
      if (a.hitInstance >= m.hits) return;
    }
    const hurtCache = new Map(defenders.map((d) => [d, fighterHurtboxes(d)]));
    for (const box of boxes) {
      const wb = sweptWorldBox(box, a);
      for (const d of defenders) {
        if (d === a) continue;
        if (a.hitList.has(d)) continue;
        if (d.invuln > 0) continue;
        const hurt = hurtCache.get(d) || [];
        for (const h of hurt) {
          if (!overlap(wb, h)) continue;
          const point = {
            x: (Math.max(wb.x, h.x) + Math.min(wb.x + wb.w, h.x + h.w)) / 2,
            y: (Math.max(wb.y, h.y) + Math.min(wb.y + wb.h, h.y + h.h)) / 2,
          };
          const hit = Object.assign({}, m, { kind: m.kind || 'normal', pushHit: m.pushHit, pushBlock: m.pushBlock });
          const res = this.applyHit(d, a, hit, point, m.color);
          a.hitList.add(d);
          if (res) break;
        }
      }
    }
  }

  applyHit(victim, attacker, hit, point, color) {
    const blocked = victim.checkBlock(hit);
    const scale = victim.comboScaling();
    const dmg = hit.percentMaxHp
      ? victim.maxHp * hit.percentMaxHp
      : Math.max(1, hit.damage * scale);
    const ok = victim.takeHit(hit, attacker, point);
    if (!ok) return false;

    const heavy = hit.hitstop >= 7;
    this.hitstop = Math.max(this.hitstop, hit.hitstop);
    this.shake = Math.max(this.shake, blocked ? 3 : heavy ? 8 : 4);

    if (blocked) {
      spawnSpark(point.x, point.y, '#a8ecff', 8, 0.8);
      spawnRing(point.x, point.y, '#7fd6ff', 58, 0.2);
      Audio.sfx.block();
    } else {
      spawnSpark(point.x, point.y, color || '#ffd21f', heavy ? 22 : 12, heavy ? 1.3 : 1);
      spawnRing(point.x, point.y, '#ffffff', heavy ? 120 : 78, heavy ? 0.32 : 0.22);
      if (hit.kind === 'hyper' || hit.type === 'hyper') Audio.sfx.hyper();
      else if (hit.level === 'mid' && hit.hitstop >= 7) Audio.sfx.heavy();
      /* contador de combo */
      victim.comboHits++;
      victim.comboResetTimer = 90;
      const atkTeam = attacker.team;
      atkTeam.combo.hits = victim.comboHits;
      atkTeam.combo.damage += dmg;
      atkTeam.combo.timer = 100;
      atkTeam.combo.label = comboLabel(victim.comboHits);
      victim.lastHitBy = attacker;
    }
    if (hit.knockdown && !blocked && victim.onGround) victim.hardLand = true;
    return true;
  }

  /* ---------------- Ciclo ---------------- */
  step(inputs) {
    if (this.teams[1]) this.teams[1].gauge = MAX_SUPER_LEVELS * SUPER_LEVEL;
    if (this.paused || this.over) { updateFx(STEP); return; }
    this.frame++;

    if (this.superFlash) {
      this.superFlash.frames--;
      updateFx(STEP);
      if (this.superFlash.frames <= 0) this.superFlash = null;
      return;
    }
    if (this.hitstop > 0) {
      this.hitstop--;
      updateFx(STEP);
      return;
    }
    if (this.announceTimer > 0) this.announceTimer--;

    this.teams[1].update(inputs[1]);
    this.teams[2].update(inputs[2]);

    /* Separación física y empuje */
    const a = this.teams[1].active, b = this.teams[2].active;
    if (a && b && a.alive && b.alive && a.onGround && b.onGround
      && !a.isDown() && !b.isDown() && a.state !== STATE.TAGIN && b.state !== STATE.TAGIN) {
      const gap = b.x - a.x;
      /* Separación suave: evita que los cuerpos se monten, pero no crea una
       * pared invisible cuando el jugador quiere retroceder o acercarse. */
      const minGap = 42;
      if (Math.abs(gap) < minGap) {
        const dir = gap === 0 ? 1 : sign(gap);
        const push = Math.min((minGap - Math.abs(gap)) * 0.5, 8);
        const canPushA = !(a.x <= WALL_L + 1 && dir < 0) && !(a.x >= WALL_R - 1 && dir > 0);
        const canPushB = !(b.x <= WALL_L + 1 && dir > 0) && !(b.x >= WALL_R - 1 && dir < 0);
        if (canPushA) a.x = clamp(a.x - dir * push, WALL_L, WALL_R);
        if (canPushB) b.x = clamp(b.x + dir * push, WALL_L, WALL_R);
      }
    }

    if (this.finalStage) {
      this.hazardTimer++;
      if (this.hazardTimer % 40 === 1) this.spawnHazard();
    }
    this.resolveHits();
    this.projectiles.forEach((p) => p.update());

    /* temporizador */
    this.timer = Math.max(0, this.timer - STEP);
    if (this.timer <= 0) this.timeUp();
    if (this.boss) this.updateBoss();

    this.checkKO();
    if (this.teams[1]) this.teams[1].gauge = MAX_SUPER_LEVELS * SUPER_LEVEL;
    updateFx(STEP);
    if (this.shake > 0) this.shake *= 0.86;
  }

  updateBoss() {
    const boss = this.teams[2].members[0];
    if (!boss || !boss.isBoss) return;
    const foe = this.teams[1].active;
    if (foe) boss.facing = foe.x > boss.x ? 1 : -1;
    this.bossRayCooldown = Math.max(0, this.bossRayCooldown - STEP);
    const chargeReady = this.bossId === 'miguel1' || this.bossId === 'miguel2'
      ? this.updateMiguelCharge(boss)
      : this.bossRayCooldown <= 0;
    if (chargeReady && !this.bossBeam && (this.bossId === 'miguel2' || !this.bossBeamUsed)) {
      this.bossBeamUsed = this.bossId === 'miguel1';
      this.bossRayCooldown = this.bossId === 'miguel2' ? rand(1.0, 1.8) : 999;
      if (this.bossId === 'miguel2' && foe) boss.x = clamp(foe.x, WALL_L + 80, WALL_R - 80);
      this.bossBeam = { t: 0, shots: 0, hitDone: false, activeAfter: 0.35, duration: 1.35, jumpVy: -17.5,
        range: this.bossId === 'miguel1' ? 360 : 180 };
      if (this.bossId === 'miguel2') {
        boss.state = STATE.IDLE;
        boss.onGround = false;
        boss.vy = 0;
        boss.y = GROUND_Y - 220;
        const c = this.bossCharge;
        if (c) { c.frames = 0; c.delay = 180; }
      } else {
        boss.state = STATE.JUMP;
        boss.onGround = false;
        boss.superJumping = false;
        boss.vy = this.bossBeam.jumpVy;
        boss.vx = boss.facing * 1.6;
        spawnDust(boss.x, GROUND_Y, boss.facing);
      }
      spawnRing(boss.x, boss.y - 24, '#ff1533', 140, 0.45);
      Audio.sfx.superFlash();
      if (this.bossId !== 'miguel2') this.announce('MIGUEL SALTA · RAYO · 3 PROYECTILES O ESQUIVA', 2.4);
    }
    if (this.bossBeam) {
      this.bossBeam.t += STEP;
      this.resolveBossBeam();
      if (this.bossBeam && this.bossBeam.t > this.bossBeam.duration && !this.over) {
        this.bossBeam = null;
        boss.state = STATE.IDLE;
        boss.vx = 0;
        if (this.bossId !== 'miguel2') this.announce('RAYO SUPERADO', 1.2);
      }
    }
  }

  updateMiguelCharge(boss) {
    const c = this.bossCharge;
    if (!c || (this.bossBeamUsed && this.bossId !== 'miguel2') || !boss.alive) return false;
    if (boss.isStunned() || boss.isDown()) {
      c.frames = 0;
      c.delay = 90;
      return false;
    }
    if (c.delay > 0) { c.delay--; return false; }
    c.frames++;
    return c.frames >= c.required;
  }

  resolveBossBeam() {
    const beam = this.bossBeam;
    if (!beam || beam.t < beam.activeAfter) return;
    const boss = this.teams[2].members[0];
    const target = this.teams[1].active;
    if (!boss || !target || !target.alive || beam.hitDone) return;
    if (target.specialEvadeTimer > 0) return;
    if (target.doubleJumpAvailable === false && !target.onGround) return;
    if (this.bossId === 'miguel2') {
      /* Rayo vertical: Miguel 2 se alinea en X y descarga hacia el piso. */
      if (Math.abs(target.x - boss.x) > beam.range) return;
      const box = { x: boss.x - 58, y: boss.y - 10, w: 116, h: GROUND_Y - boss.y + 50 };
      if (!fighterHurtboxes(target).some((h) => overlap(box, h))) return;
    } else {
      if (Math.abs(target.x - boss.x) > beam.range) return;
      const box = { x: Math.min(boss.x, target.x) - 100, y: boss.y - 310, w: Math.abs(target.x - boss.x) + 200, h: 190 };
      if (!fighterHurtboxes(target).some((h) => overlap(box, h))) return;
    }
    const rayDamage = this.bossId === 'miguel2' ? target.maxHp * 0.10 : target.hp;
    target.hp = Math.max(0, target.hp - rayDamage);
    target.redHp = Math.min(target.maxHp - target.hp, target.redHp + rayDamage * 0.55);
    beam.hitDone = true;
    target.state = target.hp <= 0 ? STATE.KO : STATE.HITSTUN;
    target.stateFrame = 0;
    target.stunFrames = 24;
    target.vx = -boss.facing * 5;
    target.vy = -7;
    target.onGround = false;
    Audio.sfx.ko();
    if (this.bossId !== 'miguel2') this.announce('RAYO ROJO · K.O.', 1.4);
  }

  timeUp() {
    if (this.over) return;
    const h1 = this.teams[1].members.reduce((s, m) => s + Math.max(0, m.hp), 0);
    const h2 = this.teams[2].members.reduce((s, m) => s + Math.max(0, m.hp), 0);
    if (this.boss) return;
    this.finish(h1 > h2 ? 1 : h2 > h1 ? 2 : 0, 'TIME OUT');
  }

  checkKO() {
    if (this.boss) {
      const boss = this.teams[2].members[0];
      if (boss && !boss.alive) this.finish(1, `${this.bossId === 'miguel1' ? 'MIGUEL 1' : 'MIGUEL 2'} DERROTADO`);
      return;
    }
    for (const side of [1, 2]) {
      const t = this.teams[side];
      if (t.defeated) {
        this.finish(side === 1 ? 2 : 1, 'K.O.');
        return;
      }
    }
  }

  finish(winner, reason) {
    if (this.over) return;
    this.over = true;
    this.winner = winner;
    this.result = reason;
    Audio.sfx.ko();
    this.announce(reason, 1.6);
  }
}

function comboLabel(n) {
  if (n < 2) return '';
  if (n === 2) return '2 HITS!';
  if (n === 3) return '3 HITS! GOOD!';
  if (n <= 5) return `${n} HITS! GREAT!`;
  if (n <= 9) return `${n} HITS! MARVELOUS!`;
  if (n <= 14) return `${n} HITS! SPECTACULAR!`;
  return `${n} HITS! UNBELIEVABLE!`;
}

/* ======================= HUD ESTILO ARCADE (CANVAS) ===================== */

const HUD = {
  fonts: { ui: '900 26px Impact, "Arial Black", sans-serif', big: '900 64px Impact, "Arial Black", sans-serif' },

  rect(g, x, y, w, h, r = 6) {
    g.beginPath();
    g.moveTo(x + r, y);
    g.arcTo(x + w, y, x + w, y + h, r);
    g.arcTo(x + w, y + h, x, y + h, r);
    g.arcTo(x, y + h, x, y, r);
    g.arcTo(x, y, x + w, y, r);
    g.closePath();
  },

  draw(g, world) {
    if (!world) return;
    const t1 = world.teams[1], t2 = world.teams[2];
    this.drawTeam(g, t1, 'left', world);
    this.drawTeam(g, t2, 'right', world);
    this.drawTimer(g, world);
    this.drawGauge(g, t1, 'left');
    this.drawGauge(g, t2, 'right');
    this.drawCombos(g, world);
    this.drawAnnounce(g, world);
    if (world.superFlash) this.drawSuperFlash(g, world.superFlash);
  },

  drawTeam(g, team, side, world) {
    const left = side === 'left';
    const barW = 470, barH = 26;
    const x = left ? 26 : VW - 26 - barW;
    const y = 90;
    const act = team.active;

    /* Marco + retrato del activo */
    const portR = 52;
    const portX = left ? 22 : VW - 22 - portR * 2;
    const portY = y - 34;
    g.save();
    g.fillStyle = 'rgba(6,8,24,0.86)';
    this.rect(g, portX, portY, portR * 2, portR * 2, 10); g.fill();
    g.strokeStyle = act.char.chroma; g.lineWidth = 3;
    g.shadowColor = act.char.chroma; g.shadowBlur = 14;
    this.rect(g, portX, portY, portR * 2, portR * 2, 10); g.stroke();
    g.shadowBlur = 0;
    /* retrato recortado del sprite en reposo */
    const art = Art.get(act.charId);
    const im = art.frames[POSE[act.char.bank].idle];
    if (im) {
      const natW = im.naturalWidth || im.width, natH = im.naturalHeight || im.height;
      const scale = (portR * 2.5) / natH;
      g.save();
      this.rect(g, portX, portY, portR * 2, portR * 2, 10); g.clip();
      g.globalAlpha = act.alive ? 1 : 0.4;
      if (['crater', 'wero'].includes(act.char.bank)) { g.translate(portX + portR * 2, 0); g.scale(-1, 1); }
      g.drawImage(im, (portX + portR) - (natW * scale) / 2, portY + portR * 2 - natH * scale * 0.98, natW * scale, natH * scale);
      g.restore();
    }
    if (!act.alive) {
      g.fillStyle = 'rgba(120,0,0,0.55)'; this.rect(g, portX, portY, portR * 2, portR * 2, 10); g.fill();
      g.strokeStyle = '#ff3b52'; g.lineWidth = 6;
      g.beginPath(); g.moveTo(portX + 12, portY + 12); g.lineTo(portX + portR * 2 - 12, portY + portR * 2 - 12); g.stroke();
      g.beginPath(); g.moveTo(portX + portR * 2 - 12, portY + 12); g.lineTo(portX + 12, portY + portR * 2 - 12); g.stroke();
    }
    g.restore();

    /* Barra principal */
    g.save();
    g.fillStyle = 'rgba(4,6,20,0.9)';
    this.rect(g, x, y, barW, barH, 7); g.fill();
    g.strokeStyle = 'rgba(255,255,255,0.92)'; g.lineWidth = 3;
    this.rect(g, x, y, barW, barH, 7); g.stroke();

    const hpPct = clamp(act.hp / act.maxHp, 0, 1);
    const redPct = clamp((act.hp + act.redHp) / act.maxHp, 0, 1);
    const drawSeg = (pct, fill) => {
      const w = barW * pct;
      g.save();
      this.rect(g, x, y, barW, barH, 7); g.clip();
      if (left) g.fillRect(x, y, w, barH); else g.fillRect(x + barW - w, y, w, barH);
      g.restore();
    };
    g.fillStyle = '#8d1230'; drawSeg(redPct, true);
    const grad = g.createLinearGradient(x, y, x, y + barH);
    grad.addColorStop(0, '#ffffff');
    grad.addColorStop(0.28, '#ffe14a');
    grad.addColorStop(0.72, '#ff9a1f');
    grad.addColorStop(1, '#ff3b2f');
    g.fillStyle = grad; drawSeg(hpPct, true);
    g.restore();

    /* Nombre */
    g.save();
    g.font = '900 22px Impact, "Arial Black", sans-serif';
    g.textAlign = left ? 'left' : 'right';
    g.fillStyle = '#fff';
    g.strokeStyle = '#000'; g.lineWidth = 5;
    g.strokeText(act.char.name, left ? x + 6 : x + barW - 6, y - 8);
    g.fillText(act.char.name, left ? x + 6 : x + barW - 6, y - 8);
    g.restore();

  },

  drawGauge(g, team, side) {
    const left = side === 'left';
    const segW = 62, segH = 16, gap = 4;
    const total = MAX_SUPER_LEVELS * (segW + gap) - gap;
    const x = left ? 26 : VW - 26 - total;
    const y = VH - 46;
    const levels = team.gauge / SUPER_LEVEL;
    g.save();
    for (let i = 0; i < MAX_SUPER_LEVELS; i++) {
      const sx = left ? x + i * (segW + gap) : x + total - segW - i * (segW + gap);
      const fill = clamp(levels - i, 0, 1);
      g.fillStyle = 'rgba(4,6,20,0.9)';
      this.rect(g, sx, y, segW, segH, 3); g.fill();
      if (fill > 0) {
        const grad = g.createLinearGradient(sx, y, sx, y + segH);
        grad.addColorStop(0, '#a9f4ff');
        grad.addColorStop(0.5, '#3aa6ff');
        grad.addColorStop(1, '#1b46c8');
        g.fillStyle = grad;
        g.save(); this.rect(g, sx, y, segW, segH, 3); g.clip();
        if (left) g.fillRect(sx, y, segW * fill, segH); else g.fillRect(sx + segW * (1 - fill), y, segW * fill, segH);
        g.restore();
      }
      g.strokeStyle = 'rgba(255,255,255,0.75)'; g.lineWidth = 2;
      this.rect(g, sx, y, segW, segH, 3); g.stroke();
    }
    /* Nivel numérico */
    g.font = '900 30px Impact, sans-serif';
    g.fillStyle = levels >= MAX_SUPER_LEVELS ? '#ffd21f' : '#fff';
    g.strokeStyle = '#000'; g.lineWidth = 5;
    g.textAlign = left ? 'left' : 'right';
    const lx = left ? x + total + 16 : x - 16;
    g.strokeText(`${Math.floor(levels)}`, lx, y + segH);
    g.fillText(`${Math.floor(levels)}`, lx, y + segH);
    g.font = '900 13px Impact, sans-serif';
    g.fillStyle = '#8fe6ff';
    g.strokeText('HYPER', left ? x : x + total, y - 6);
    g.fillText('HYPER', left ? x : x + total, y - 6);
    g.restore();
  },

  drawTimer(g, world) {
    const t = Math.max(0, Math.ceil(world.timer));
    g.save();
    g.textAlign = 'center';
    g.font = '900 62px Impact, "Arial Black", sans-serif';
    const txt = String(t).padStart(2, '0');
    g.fillStyle = 'rgba(5,6,22,0.82)';
    this.rect(g, VW / 2 - 66, 20, 132, 84, 10); g.fill();
    g.strokeStyle = t <= 10 ? '#ff3b52' : '#ffd21f'; g.lineWidth = 4;
    this.rect(g, VW / 2 - 66, 20, 132, 84, 10); g.stroke();
    g.fillStyle = t <= 10 ? '#ff5c6e' : '#fff';
    g.strokeStyle = '#000'; g.lineWidth = 7;
    g.strokeText(txt, VW / 2, 84);
    g.fillText(txt, VW / 2, 84);
    /* número de combate */
    g.font = '900 15px Impact, sans-serif';
    g.fillStyle = '#8fe6ff';
    g.fillText(world.label || '', VW / 2, 122);
    g.restore();
  },

  drawCombos(g, world) {
    const draw = (team, side) => {
      if (team.combo.hits < 2 || team.combo.timer <= 0) return;
      const left = side === 'left';
      const x = left ? 120 : VW - 120;
      const y = 250;
      g.save();
      g.textAlign = left ? 'left' : 'right';
      g.font = '900 54px Impact, "Arial Black", sans-serif';
      const pop = 1 + Math.sin(world.frame * 0.4) * 0.03;
      g.translate(x, y); g.scale(pop, pop);
      g.strokeStyle = '#000'; g.lineWidth = 10;
      g.strokeText(team.combo.label, 0, 0);
      const grad = g.createLinearGradient(0, -40, 0, 10);
      grad.addColorStop(0, '#fff');
      grad.addColorStop(0.5, '#ffd21f');
      grad.addColorStop(1, '#ff7a1f');
      g.fillStyle = grad;
      g.fillText(team.combo.label, 0, 0);
      g.font = '900 20px Impact, sans-serif';
      g.fillStyle = '#8fe6ff';
      g.strokeStyle = '#000'; g.lineWidth = 6;
      g.strokeText(`${Math.round(team.combo.damage)} PTS`, 0, 28);
      g.fillText(`${Math.round(team.combo.damage)} PTS`, 0, 28);
      g.restore();
    };
    draw(world.teams[1], 'left');
    draw(world.teams[2], 'right');
  },

  drawAnnounce(g, world) {
    if (!world.announceTimer || !world.announce_text) return;
    const a = world.announceTimer;
    const alpha = clamp(a / 20, 0, 1);
    const scale = 1 + Math.max(0, (a - 40) / 60) * 0.5;
    g.save();
    g.globalAlpha = alpha;
    g.textAlign = 'center';
    g.translate(VW / 2, VH * 0.34);
    g.scale(scale, scale);
    g.font = '900 82px Impact, "Arial Black", sans-serif';
    g.strokeStyle = '#000'; g.lineWidth = 12;
    g.strokeText(world.announce_text, 0, 0);
    const grad = g.createLinearGradient(0, -60, 0, 20);
    grad.addColorStop(0, '#ffffff');
    grad.addColorStop(0.55, '#ffd21f');
    grad.addColorStop(1, '#ff2bd6');
    g.fillStyle = grad;
    g.fillText(world.announce_text, 0, 0);
    g.restore();
  },

  drawSuperFlash(g, flash) {
    const t = 1 - flash.frames / flash.total;
    g.save();
    g.globalAlpha = 0.55 + 0.25 * Math.sin(flash.frames * 0.9);
    const grad = g.createRadialGradient(flash.fighter.x, flash.fighter.y - 130, 20, flash.fighter.x, flash.fighter.y - 130, 620);
    grad.addColorStop(0, flash.move.color);
    grad.addColorStop(0.4, 'rgba(20,10,60,0.85)');
    grad.addColorStop(1, 'rgba(2,2,12,0.96)');
    g.fillStyle = grad;
    g.fillRect(0, 0, VW, VH);
    g.restore();
    /* retrato grande durante el flash */
    const art = Art.get(flash.fighter.charId);
    const mysticSpecial = flash.fighter.charId === 'wzm' ? SpecialArt.wizzMystic : null;
    const suppliedSpecial = flash.move.id === 'hyUlt' ? SpecialArt[flash.fighter.charId] : null;
    const isSuppliedSpecial = !!(suppliedSpecial?.complete && suppliedSpecial.naturalWidth > 0);
    const specialPortrait = isSuppliedSpecial ? suppliedSpecial : (mysticSpecial?.complete ? mysticSpecial : null);
    const im = specialPortrait || (art.frames[POSE[flash.fighter.char.bank].hyper] || art.frames[0]);
    if (im) {
      const natW = im.naturalWidth || im.width, natH = im.naturalHeight || im.height;
      const w = isSuppliedSpecial ? natW * (Math.min(520, VH - 180) / natH) : (mysticSpecial ? Math.min(1120, natW) : natW * (520 / natH));
      const h = (isSuppliedSpecial || mysticSpecial) ? natH * (w / natW) : 520;
      g.save();
      g.globalAlpha = clamp(flash.frames / flash.total * 1.5, 0, 1);
      g.filter = `drop-shadow(0 0 40px ${flash.move.color})`;
      g.drawImage(im, VW / 2 - w / 2, (isSuppliedSpecial || mysticSpecial) ? VH / 2 - h / 2 + 20 : VH - h + 40, w, h);
      g.filter = 'none';
      g.restore();
    }
    g.save();
    g.textAlign = 'center';
    g.font = '900 44px Impact, sans-serif';
    g.fillStyle = flash.move.color;
    g.strokeStyle = '#000'; g.lineWidth = 9;
    g.strokeText(flash.move.name, VW / 2, 150);
    g.fillText(flash.move.name, VW / 2, 150);
    g.restore();
  },
};

/* ======================= RENDER DEL COMBATE ============================ */

function drawStage(g) {
  g.fillStyle = '#06081c';
  g.fillRect(0, 0, VW, VH);
  const bg = WORLD && WORLD.finalStage ? FINAL_STAGE_BG : STAGE_BG;
  if (bg.complete && bg.naturalWidth > 0) {
    const natW = bg.naturalWidth, natH = bg.naturalHeight;
    const scale = Math.max(VW / natW, VH / natH);
    const w = natW * scale, h = natH * scale;
    g.drawImage(bg, (VW - w) / 2, (VH - h) / 2, w, h);
  }
  const shade = g.createLinearGradient(0, 0, 0, VH);
  shade.addColorStop(0, 'rgba(4,6,24,0.30)');
  shade.addColorStop(0.62, 'rgba(4,6,24,0.05)');
  shade.addColorStop(1, 'rgba(3,4,18,0.55)');
  g.fillStyle = shade;
  g.fillRect(0, 0, VW, VH);
  /* línea de piso */
  g.save();
  g.globalAlpha = 0.5;
  g.strokeStyle = 'rgba(140,220,255,0.55)';
  g.lineWidth = 3;
  g.beginPath(); g.moveTo(0, GROUND_Y + 4); g.lineTo(VW, GROUND_Y + 4); g.stroke();
  g.restore();
}

function drawBossBeam(g, world) {
  if (!world.bossBeam && world.bossId === 'miguel2') return;
  if (!world.bossBeam) {
    const c = world.bossCharge;
    if (!c || world.bossBeamUsed) return;
    const boss = world.teams[2].members[0];
    if (!boss) return;
    const progress = clamp(c.frames / c.required, 0, 1);
    g.save();
    g.textAlign = 'center';
    g.font = '900 24px Impact, sans-serif';
    g.fillStyle = '#ff9a6a';
    g.strokeStyle = '#000'; g.lineWidth = 6;
    g.strokeText(`MIGUEL 1 · CARGA ${c.buttons}`, VW / 2, 76);
    g.fillText(`MIGUEL 1 · CARGA ${c.buttons}`, VW / 2, 76);
    g.fillStyle = 'rgba(0,0,0,.72)'; g.fillRect(VW / 2 - 190, 88, 380, 16);
    g.fillStyle = '#ff1533'; g.fillRect(VW / 2 - 186, 92, 372 * progress, 8);
    g.restore();
    return;
  }
  const t = clamp(world.bossBeam.t / 0.35, 0, 1);
  const boss = world.teams[2].members[0];
  const foe = world.teams[1].active;
  if (!boss || !foe) return;
  if (world.bossId === 'miguel2') {
    const pulse = 1 + Math.sin(world.bossBeam.t * 46) * 0.14;
    const top = boss.y - 8, bottom = GROUND_Y + 18, width = 54 * pulse;
    g.save();
    g.globalCompositeOperation = 'lighter';
    g.shadowColor = '#ff1029'; g.shadowBlur = 46;
    g.fillStyle = 'rgba(255,40,48,0.22)';
    g.fillRect(boss.x - width, top, width * 2, bottom - top);
    g.shadowBlur = 16;
    g.fillStyle = 'rgba(255,0,34,0.90)';
    g.fillRect(boss.x - width * 0.45, top, width * 0.9, bottom - top);
    g.fillStyle = 'rgba(255,248,245,0.95)';
    g.fillRect(boss.x - 7, top, 14, bottom - top);
    g.strokeStyle = '#ff1533'; g.lineWidth = 12;
    g.beginPath(); g.arc(boss.x, bottom - 8, 45 + world.bossBeam.t * 18, 0, Math.PI * 2); g.stroke();
    g.restore();
    return;
  }
  const y = boss.y - 250;
  const beamEnd = boss.x + boss.facing * (world.bossBeam.range || VW);
  const left = Math.min(boss.x, beamEnd) - 90;
  const right = Math.max(boss.x, beamEnd) - 70;
  const width = Math.max(0, right - left);
  const pulse = 1 + Math.sin(world.bossBeam.t * 46) * 0.14;
  g.save();
  g.globalCompositeOperation = 'lighter';
  const grad = g.createLinearGradient(right, y, left, y);
  grad.addColorStop(0, 'rgba(255,255,255,1)');
  grad.addColorStop(0.14, 'rgba(255,52,56,0.98)');
  grad.addColorStop(0.7, 'rgba(255,0,34,0.9)');
  grad.addColorStop(1, 'rgba(255,40,48,0.14)');
  g.shadowColor = '#ff1029'; g.shadowBlur = 46;
  g.fillStyle = grad;
  g.fillRect(left, y - 32 * pulse, width, 64 * pulse);
  g.shadowBlur = 16;
  g.fillStyle = 'rgba(255,248,245,0.95)';
  g.fillRect(left, y - 8 * pulse, width, 16 * pulse);
  const r = 50 + world.bossBeam.t * 30;
  g.globalAlpha = 0.85;
  g.strokeStyle = '#fff'; g.lineWidth = 5;
  g.beginPath(); g.arc(foe.x, y, r, 0, Math.PI * 2); g.stroke();
  g.strokeStyle = '#ff1533'; g.lineWidth = 15;
  g.beginPath(); g.arc(foe.x, y, r + 14, 0, Math.PI * 2); g.stroke();
  g.restore();
}

function drawFight(g, world) {
  g.save();
  if (world.finalStage) world.shake = Math.max(world.shake || 0, 2.6);
  if (world.shake > 0.3) g.translate(rand(-world.shake, world.shake), rand(-world.shake, world.shake));
  drawStage(g);

  /* estelas */
  for (const a of Afterimages) {
    const art = Art.get(a.charId);
    const im = a.img;
    if (!im) continue;
    const natW = im.naturalWidth || im.width, natH = im.naturalHeight || im.height;
    const h = FIGHTER_DRAW_HEIGHT, w = natW * (h / natH);
    const alpha = (1 - a.age / a.life) * a.alpha;
    g.save();
    g.globalAlpha = alpha;
    g.globalCompositeOperation = 'lighter';
    g.translate(a.x, a.y + (art.feetPad || 0));
    const spriteFacesRight = art.spriteFacesRight ?? true;
    const baseFlip = spriteFacesRight ? a.facing === -1 : a.facing === 1;
    const flip = baseFlip;
    if (flip) g.scale(-1, 1);
    g.filter = `drop-shadow(0 0 12px ${CHAR[a.charId].chroma})`;
    g.drawImage(im, -w / 2, -h, w, h);
    g.filter = 'none';
    g.restore();
  }

  /* luchadores (ordenados por profundidad) */
  const units = [];
  for (const side of [1, 2]) {
    const t = world.teams[side];
    if (t.active) units.push(t.active);
    if (t.assistActor) units.push(t.assistActor);
  }
  units.sort((a, b) => a.y - b.y);
  units.forEach((u) => u.draw(g));

  world.projectiles.forEach((p) => p.draw(g));
  drawParticles(g);
  drawBossBeam(g, world);
  if (world.finalStage) {
    const pulse = 0.5 + 0.5 * Math.sin(performance.now() / 55);
    g.save(); g.globalAlpha = 0.08 + 0.20 * pulse; g.fillStyle = '#ff1020';
    g.fillRect(-40, -40, VW + 80, VH + 80); g.restore();
  }
  g.restore();

  /* anuncio de KO / flash ya dentro del HUD */
}

function drawParticles(g) {
  for (const p of Particles) {
    const a = 1 - p.age / p.life;
    g.save();
    g.globalAlpha = clamp(a, 0, 1);
    if (p.type === 'ring') {
      const r = lerp(p.r, p.maxR, 1 - a);
      g.strokeStyle = p.color;
      g.lineWidth = p.lw * a;
      g.beginPath(); g.arc(p.x, p.y, r, 0, Math.PI * 2); g.stroke();
    } else if (p.type === 'streak') {
      g.globalCompositeOperation = 'lighter';
      g.strokeStyle = p.color;
      g.lineWidth = Math.max(1, p.size * a);
      g.lineCap = 'round';
      g.beginPath(); g.moveTo(p.x, p.y); g.lineTo(p.x - (p.dir || 1) * p.len, p.y); g.stroke();
    } else if (p.type === 'trail') {
      g.globalCompositeOperation = 'lighter';
      g.fillStyle = p.color;
      g.beginPath(); g.arc(p.x, p.y, p.size * a, 0, Math.PI * 2); g.fill();
    } else {
      g.globalCompositeOperation = 'lighter';
      g.fillStyle = p.color;
      g.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    }
    g.restore();
  }
  for (const f of Floaters) {
    const a = 1 - f.age / f.life;
    g.save();
    g.globalAlpha = clamp(a, 0, 1);
    g.textAlign = 'center';
    g.font = `900 ${f.size}px Impact, "Arial Black", sans-serif`;
    g.strokeStyle = '#000'; g.lineWidth = 7;
    g.strokeText(f.text, f.x, f.y);
    g.fillStyle = f.color;
    g.fillText(f.text, f.x, f.y);
    g.restore();
  }
}

/* ======================= MÁQUINA DE ESTADOS DEL JUEGO =================== */

const DIFFICULTY_PRESETS = { easy: 0.72, normal: 1, hard: 1.28 };
const ARCADE_ROUTE = [
  ...ROSTER.map((c, i) => ({ chars: [c.id], assists: ['a'], diff: Math.min(1.34, 0.68 + i * 0.035), label: `NIVEL ${i + 1} · ${c.name}` })),
  { chars: ['miguel1', 'crater'], assists: ['a', 'a'], diff: 0, label: 'JEFE FINAL · MIGUEL 1', boss: true, bossId: 'miguel1' },
  { chars: ['miguel2', 'crater'], assists: ['a', 'a'], diff: 0, label: 'JEFE FINAL · MIGUEL 2', boss: true, bossId: 'miguel2' },
  { chars: ['miguel2', 'crater'], assists: ['a', 'a'], diff: 0, label: 'NIVEL FINAL', boss: true, bossId: 'miguel2', final: true },
];
const MYSTIC_UNLOCK_KEY = 'dcvswiz:wizz-mistico:unlocked';
const MISTIKWIZZ_UNLOCK_KEY = 'dcvswiz:mistikwizz:unlocked';
const DCAKUMA_UNLOCK_KEY = 'dcvswiz:dcakuma:unlocked';
const MIGUEL1_UNLOCK_KEY = 'dcvswiz:miguel1:unlocked';
const MIGUEL2_UNLOCK_KEY = 'dcvswiz:miguel2:unlocked';
function isMiguel1Unlocked() { try { return localStorage.getItem(MIGUEL1_UNLOCK_KEY) === '1'; } catch (_) { return false; } }
function isMiguel2Unlocked() { try { return localStorage.getItem(MIGUEL2_UNLOCK_KEY) === '1'; } catch (_) { return false; } }
function unlockMiguels() {
  try { localStorage.setItem(MIGUEL1_UNLOCK_KEY, '1'); localStorage.setItem(MIGUEL2_UNLOCK_KEY, '1'); } catch (_) {}
}
function isMysticUnlocked() {
  try { return localStorage.getItem(MYSTIC_UNLOCK_KEY) === '1'; } catch (_) { return false; }
}
function unlockMystic() {
  try { localStorage.setItem(MYSTIC_UNLOCK_KEY, '1'); } catch (_) {}
}
function isMistikwizzUnlocked(){try{return localStorage.getItem(MISTIKWIZZ_UNLOCK_KEY)==='1';}catch(_){return false;}}
function unlockMistikwizz(){try{localStorage.setItem(MISTIKWIZZ_UNLOCK_KEY,'1');}catch(_){}}
function isDCAkumaUnlocked() {
  try { return localStorage.getItem(DCAKUMA_UNLOCK_KEY) === '1'; } catch (_) { return false; }
}
function unlockDCAkuma() {
  try { localStorage.setItem(DCAKUMA_UNLOCK_KEY, '1'); } catch (_) {}
}
/* Con DCAkuma desbloqueado la ruta se acorta: tras un combate adicional
 * se entra directamente a Miguel. El cambio también se aplica si el unlock
 * ocurre durante la primera partida. */
function arcadeRoute() {
  const mult = DIFFICULTY_PRESETS[Game.arcadeDifficulty] || DIFFICULTY_PRESETS.normal;
  return ARCADE_ROUTE.map((r) => ({ ...r, diff: r.boss ? 0 : r.diff * mult }));
}

const Game = {
  screen: 'menu',
  mode: 'arcade',
  world: null,
  stage: 0,
  wins: 0,
  losses: 0,
  arcadeComplete: false,
  arcadeDifficulty: 'easy', // fácil por defecto; la selección fue retirada del menú

  morganSceneShown: false,
  paused: false,
  p1: { picks: [], step: 0, focus: 0 },
  p2: { picks: [], step: 0, focus: 0 },
  selectSide: 1,
  result: null,
  practiceDummy: true,

  reset() {
    this.p1 = { picks: [], step: 0, focus: 0 };
    this.p2 = { picks: [], step: 0, focus: 0 };
    this.selectSide = 1;
    this.stage = 0;
    this.wins = 0;
    this.losses = 0;
    this.arcadeComplete = false;
    this.morganSceneShown = false;
    this.world = null;
  },

  startMode(mode) {
    this.mode = mode;
    this.reset();
    Audio.init(); Audio.resume();
    renderSelect();
    setScreen('select');
  },

  cpuPicks(route) {
    return [{ charId: route.chars[0] }];
  },

  beginFight() {
    const opts = {
      timer: this.mode === 'practice' ? 999 : 99,
      cpu2: this.mode !== 'versus',
    };
    let picks2;
    let diff = 0.85;
    if (this.mode === 'arcade') {
      const routeList = arcadeRoute();
      const route = routeList[this.stage];
      /* Evita quedar atrapado si una ruta cambia por un desbloqueo. */
      if (!route) {
        this.world = null;
        setScreen('menu');
        return;
      }
      picks2 = this.cpuPicks(route);
      diff = route.diff;
      opts.boss = !!route.boss;
      opts.bossId = route.bossId;
      opts.finalStage = !!route.final;
      opts.timer = route.boss ? 20 : 99;
      opts.gauge2 = route.boss ? 0 : 0;
    } else if (this.mode === 'practice') {
      picks2 = [{ charId: 'wz' }];
      diff = 0;
    } else {
      picks2 = this.p2.picks.slice();
      opts.cpu2 = false;
    }
    this.world = new World(this.mode, this.p1.picks.slice(), picks2, opts);
    this.world.label = this.mode === 'arcade' ? arcadeRoute()[this.stage].label : (this.mode === 'versus' ? 'VERSUS 2P' : 'PRÁCTICA');
    if (this.mode === 'practice') {
      const d = this.world.teams[2].active;
      d.isTrainingDummy = true;
    }
    const easyMultiplier = DIFFICULTY_PRESETS[Game.arcadeDifficulty] || DIFFICULTY_PRESETS.easy;
    const bossDiff = this.world.boss ? 1.45 * easyMultiplier : diff;
    this.world.teams[2].ai = new AiController(this.world.teams[2].active, bossDiff);
    this.world.teams[2].aiDiff = bossDiff;
    this.paused = false;
    resetFx();
    setScreen('fight');
    if (!this.world.boss || this.world.bossId !== 'miguel2') this.world.announce(this.world.boss ? 'JEFE FINAL · 20 SEGUNDOS' : 'FIGHT!', 1.5);
    Audio.sfx.round();
    /* Inicia la pista al comenzar el combate tras el gesto del usuario. */
    Audio.startMusic();
  },

  buildInputs() {
    const w = this.world;
    const out = {};
    for (const side of [1, 2]) {
      const t = w.teams[side];
      if (t.isCPU || (this.mode === 'practice' && side === 2 && this.practiceDummy)) {
        if (!t.ai) t.ai = new AiController(t.active, 0.85);
        if (t.ai.f !== t.active) t.ai = new AiController(t.active, t.aiDiff ?? 0.85);
        out[side] = t.ai.think(w);
      } else if (this.mode === 'practice' && side === 2) {
        out[side] = Input.read(KEYMAP_P2, true, 2);
      } else {
        out[side] = Input.read(side === 1 ? KEYMAP_P1 : KEYMAP_P2, true, side);
      }
    }
    return out;
  },

  advanceArcade() {
    const route = arcadeRoute();
    if (this.mode !== 'arcade' || !this.world || this.world.winner !== 1) return false;
    if (this.stage < 0 || this.stage >= route.length) { this.settlement = false; setScreen('menu'); return false; }
    this.paused = false;
    this.beginFight();
    return true;
  },
  onFightEnd() {
    const w = this.world;
    if (this.mode === 'practice') { return; }
    const usedToto = this.p1.picks.some((p) => p.charId === 'toto');
    const firstMiguel1Win = w.winner === 1 && usedToto && !isMiguel1Unlocked();
    if (firstMiguel1Win) unlockMiguel1();
    /* Tras derrotar a MIGUEL 2, Morgan cruza la pantalla lentamente de ida y
     * vuelta antes de continuar con las cinemáticas y los desbloqueos. El
     * sprite dedicado se carga si se añade después; el respaldo conserva el
     * flujo funcional mientras morgan.png todavía no está disponible. */
    if (this.mode === 'arcade' && w.winner === 1 && w.bossId === 'miguel2' && !this.morganSceneShown) {
      this.morganSceneShown = true;
      this.showMorganFlight(() => this.onFightEnd());
      return;
    }
    if (this.mode === 'arcade') {
      if (w.winner === 1) {
        this.wins++;
        const firstMistikwizzWin=w.bossId==='miguel2'&&!isMistikwizzUnlocked(); if(firstMistikwizzWin) unlockMistikwizz();
        const firstDCAkumaWin = !isDCAkumaUnlocked();
        const usedWero = this.p1.picks.some((p) => p.charId === 'wero');
        const usedFinalTeam = this.p1.picks.some((p) => ['yiyo', 'manuelin', 'crater'].includes(p.charId));
        if (firstDCAkumaWin) unlockDCAkuma();
        const proceedAfterUnlocks = () => {
          if (this.stage + 1 >= arcadeRoute().length) {
            this.playVictoryCinematic();
            return;
          }
          this.stage++;
          this.showResult(w.result, [`COMBATE GANADO`, `SIGUIENTE: ${arcadeRoute()[this.stage].label}`, 'CONTINÚA PARA AVANZAR']);
        };
        const continueAfterUnlock = () => {
          const showTeamVictoryScene = () => {
            if (usedFinalTeam) {
              this.showVictoryImage('assets/victories/final.png', 'FINAL · YIYO · MANUELÍN · CRATER', proceedAfterUnlocks);
              return;
            }
            proceedAfterUnlocks();
          };
          const showWeroScene = () => {
            if (firstMiguel1Win) {
              this.showUnlockPoster('miguel1', '¡MIGUEL 1 DESBLOQUEADO!', () => {
                showWeroScene();
              });
              return;
            }
            if (usedWero) {
              this.showVictoryImage('assets/victories/wero-level-complete.jpg', 'WERO · NIVEL SUPERADO', showTeamVictoryScene);
              return;
            }
            showTeamVictoryScene();
          };
          showWeroScene();
        };
        if (firstDCAkumaWin) {
          this.showUnlockPoster('dcakuma', '¡DCAKUMA DESBLOQUEADO!', continueAfterUnlock);
          return;
        }
        if(firstMistikwizzWin){this.showUnlockPoster('mistikwiz','¡MISTIKWIZZ DESBLOQUEADO!',continueAfterUnlock);return;}
        continueAfterUnlock();
        return;
      }
      this.showResult('GAME OVER', ['Derrota en ' + arcadeRoute()[this.stage].label, `Combates ganados: ${this.wins}`, 'VUELVE AL MENÚ PARA REINTENTAR']);
      return;
    }
    if (this.mode === 'versus') {
      const txt = w.winner === 0 ? 'EMPATE' : (w.winner === 1 ? 'JUGADOR 1 GANA' : 'JUGADOR 2 GANA');
      this.showResult(w.result, [txt, ...(firstMiguel1Win ? ['¡MIGUEL 1 DESBLOQUEADO POR GANAR CON TOTO!'] : []), `P1: ${this.p1.picks.map((p) => CHAR[p.charId].name).join('')}`, `P2: ${this.p2.picks.map((p) => CHAR[p.charId].name).join('')}`]);
    }
  },

  showMorganFlight(done) {
    const stage = $('stage');
    if (!stage) { done(); return; }
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:absolute;inset:0;z-index:47;overflow:hidden;background:linear-gradient(180deg,rgba(3,5,25,.98),rgba(12,8,35,.92));display:grid;place-items:center;';
    const style = document.createElement('style');
    style.textContent = `
      @keyframes morganFlyAcross {
        0% { transform:translateX(-42vw) translateY(10px) scaleX(1) rotate(-2deg); }
        24% { transform:translateX(-12vw) translateY(-18px) scaleX(1) rotate(2deg); }
        50% { transform:translateX(42vw) translateY(8px) scaleX(-1) rotate(-1deg); }
        74% { transform:translateX(12vw) translateY(-15px) scaleX(-1) rotate(2deg); }
        100% { transform:translateX(-42vw) translateY(10px) scaleX(1) rotate(-2deg); }
      }
      @keyframes morganGlow { 0%,100%{opacity:.55} 50%{opacity:1} }
    `;
    const glow = document.createElement('div');
    glow.style.cssText = 'position:absolute;width:38vw;height:18vw;border-radius:50%;background:radial-gradient(ellipse,rgba(87,218,255,.45),transparent 68%);filter:blur(18px);animation:morganGlow 2.8s ease-in-out infinite;';
    const img = document.createElement('img');
    img.alt = 'Morgan volando';
    img.style.cssText = 'position:absolute;width:min(31vw,360px);max-height:50vh;object-fit:contain;image-rendering:auto;animation:morganFlyAcross 12s ease-in-out 2;filter:drop-shadow(0 0 18px #59e6ff);';
    let usedFallback = false;
    img.onerror = () => {
      if (usedFallback) return;
      usedFallback = true;
      img.src = 'assets/sprites/miguel1-air.png';
    };
    img.src = 'assets/sprites/morgan.png';
    const title = document.createElement('div');
    title.textContent = 'MORGAN · VUELO FINAL';
    title.style.cssText = 'position:absolute;top:9%;left:0;right:0;text-align:center;color:#7cecff;font:900 clamp(22px,4vw,42px) Impact,sans-serif;letter-spacing:.16em;text-shadow:0 0 14px #168cff,3px 3px 0 #071126;';
    const note = document.createElement('div');
    note.textContent = 'IDA Y VUELTA · LA RUTA CONTINÚA';
    note.style.cssText = 'position:absolute;bottom:13%;left:0;right:0;text-align:center;color:#fff;font:900 clamp(12px,2vw,19px) Impact,sans-serif;letter-spacing:.1em;text-shadow:2px 2px 0 #000;';
    const skip = document.createElement('button');
    skip.textContent = 'CONTINUAR';
    skip.style.cssText = 'position:absolute;bottom:5%;left:50%;transform:translateX(-50%);padding:9px 20px;background:rgba(8,5,28,.86);color:#fff;border:2px solid #59e6ff;border-radius:8px;font:900 15px Impact,sans-serif;cursor:pointer;';
    let finished = false;
    let timer;
    const finish = () => { if (finished) return; finished = true; clearTimeout(timer); overlay.remove(); done(); };
    skip.onclick = finish;
    img.addEventListener('animationend', finish, { once: true });
    timer = setTimeout(finish, 24500);
    overlay.append(style, glow, img, title, note, skip);
    stage.appendChild(overlay);
    setTimeout(() => skip.focus(), 0);
  },
  showResult(title, lines) {
    $('resultTitle').textContent = title;
    $('resultStats').innerHTML = lines.map((l) => `<div>${l}</div>`).join('');
    const cont = $('btn-continue');
    cont.textContent = this.arcadeComplete ? 'VOLVER AL MENÚ' : ((this.mode === 'arcade' && this.world && this.world.winner === 1 && this.stage < arcadeRoute().length && this.stage > 0) ? 'SIGUIENTE COMBATE' : 'JUGAR OTRA VEZ');
    setScreen('result');
    Audio.sfx.ok();
  },

  showUnlockPoster(kind, title, done) {
    const poster = kind === 'mistikwiz'
      ? (Art.get('mistikwiz').frames[POSE.mistikwiz.idle]?.src || UNLOCK_ART.wizz)
      : kind === 'miguel1'
        ? SELECT_PORTRAITS.miguel1
        : UNLOCK_ART[kind];
    if (!poster) { done(); return; }
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483647;width:100vw;height:100vh;height:100dvh;overflow:hidden;background:#000;display:grid;place-items:center;touch-action:manipulation;';
    overlay.tabIndex = 0;
    overlay.setAttribute('role', 'button');
    overlay.setAttribute('aria-label', `${title}. Pulsa Enter o toca para continuar.`);
    const img = document.createElement('img');
    img.src = poster; img.alt = title;
    img.style.cssText = 'width:100vw;height:100vh;height:100dvh;object-fit:contain;display:block;';
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      window.removeEventListener('keydown', onKey);
      overlay.remove();
      done();
    };
    const onKey = (e) => {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') { e.preventDefault(); finish(); }
    };
    overlay.addEventListener('click', finish);
    window.addEventListener('keydown', onKey);
    img.onerror = finish;
    overlay.appendChild(img);
    document.body.appendChild(overlay);
    setTimeout(() => overlay.focus(), 0);
  },

  showVictoryImage(src, title, done) {
    if (!src) { done(); return; }
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483647;width:100vw;height:100vh;height:100dvh;overflow:hidden;background:#000;display:grid;place-items:center;touch-action:manipulation;';
    overlay.tabIndex = 0;
    overlay.setAttribute('role', 'button');
    overlay.setAttribute('aria-label', `${title}. Pulsa Enter o toca para continuar.`);
    const img = document.createElement('img');
    img.src = src; img.alt = title; img.loading = 'eager';
    img.style.cssText = 'width:100vw;height:100vh;height:100dvh;object-fit:contain;display:block;';
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      window.removeEventListener('keydown', onKey);
      overlay.remove();
      done();
    };
    const onKey = (e) => {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Escape') { e.preventDefault(); finish(); }
    };
    overlay.addEventListener('click', finish);
    window.addEventListener('keydown', onKey);
    img.onerror = finish;
    overlay.appendChild(img);
    document.body.appendChild(overlay);
    setTimeout(() => overlay.focus(), 0);
  },
  playVictoryCinematic() {
    const stage = $('stage');
    if (!stage) { this.finishMysticUnlock(); return; }
    const usedCrater = this.p1.picks.some((p) => p.charId === 'crater');
    const usedTotoOrYiyo = this.p1.picks.some((p) => p.charId === 'toto' || p.charId === 'yiyo');
    const usedDc = this.p1.picks.some((p) => /^dc/.test(p.charId));
    const usedWizz = this.p1.picks.some((p) => /^wz/.test(p.charId));
    /* Clips específicos preceden a las cinemáticas existentes; el nuevo clip
     * cubre únicamente a los personajes sin video propio. */
    const cinematicSrc = usedCrater
      ? 'assets/video/crater-victory.mp4'
      : usedTotoOrYiyo
        ? 'assets/video/toto-yiyo-victory.mp4'
        : usedDc && !usedWizz
          ? 'assets/video/miguel-victory.mp4'
          : usedWizz
            ? 'assets/video/miguel-victory-wizz.mp4'
            : 'assets/video/victory-generic.mp4';
    Audio.stopMusic();
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483647;width:100vw;height:100vh;height:100dvh;overflow:hidden;background:#000;display:grid;place-items:center;';
    const video = document.createElement('video');
    video.src = cinematicSrc;
    video.autoplay = true; video.playsInline = true; video.controls = false;
    video.style.cssText = 'width:100vw;height:100vh;height:100dvh;object-fit:contain;background:#000;';
    overlay.appendChild(video);
    document.body.appendChild(overlay);
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      window.removeEventListener('keydown', onKey);
      overlay.remove();
      this.finishMysticUnlock();
    };
    const onKey = (e) => {
      if (e.key === 'Escape' || e.key === ' ' || e.key === 'Enter') { e.preventDefault(); finish(); }
    };
    overlay.addEventListener('click', () => {
      if (video.paused) video.play().catch(() => {});
      else if (video.duration > 30) finish();
    });
    window.addEventListener('keydown', onKey);
    video.onended = finish;
    video.onerror = finish;
    video.play().catch(() => {});
  },

  playGameOverVideo(done) {
    const stage = $('stage');
    if (!stage) { done(); return; }
    const overlay = document.createElement('div');
    overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483647;width:100vw;height:100vh;height:100dvh;background:#000;display:grid;place-items:center;overflow:hidden;';
    const video = document.createElement('video');
    video.src = 'assets/video/gameover-final.mp4';
    video.autoplay = true; video.playsInline = true; video.controls = false;
    video.style.cssText = 'width:100vw;height:100vh;height:100dvh;object-fit:contain;background:#000;';
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      window.removeEventListener('keydown', onKey);
      overlay.remove();
      done();
    };
    const onKey = (e) => { if (e.key === 'Escape' || e.key === ' ' || e.key === 'Enter') { e.preventDefault(); finish(); } };
    overlay.addEventListener('click', () => {
      if (video.paused) video.play().catch(() => {});
      else finish();
    });
    video.onended = finish;
    video.onerror = finish;
    window.addEventListener('keydown', onKey);
    overlay.appendChild(video);
    document.body.appendChild(overlay);
    video.play().catch(() => {});
  },
  finishMysticUnlock() {
    this.arcadeComplete = true;
    const already = isMysticUnlocked();
    const miguelsAlready = isMiguel1Unlocked() && isMiguel2Unlocked();
    unlockMiguels();
    unlockMystic();
    const finish = () => this.showResult('¡VICTORIA TOTAL!', [
      'Has superado la ruta arcade completa',
      `Combates ganados: ${this.wins}`,
      already ? 'WIZZ MÍSTICO · YA DESBLOQUEADO' : '¡WIZZ MÍSTICO DESBLOQUEADO!',
      miguelsAlready ? 'MIGUEL 1 · MIGUEL 2 · YA DESBLOQUEADOS' : '¡MIGUEL 1 Y MIGUEL 2 DESBLOQUEADOS!',
      'RANDOM: 50% PERSONAJE · 30% MIGUEL 1 · 20% MIGUEL 2',
      'DC LABORATORIO TE ESPERA',
    ]);
    /* fin.png es la última escena: aparece después de la cinemática final
     * y después del póster de desbloqueo de Wizz Místico. */
    const showFinalScene = () => this.playGameOverVideo(() => this.showVictoryImage(
      'assets/victories/fin.png', 'FIN · RUTA ARCADE COMPLETADA', finish,
    ));
    if (!already) this.showUnlockPoster('wizz', '¡WIZZ MÍSTICO DESBLOQUEADO!', showFinalScene);
    else showFinalScene();
  },
};

/* ======================= PANTALLAS (DOM) =============================== */

function $(id) { return document.getElementById(id); }

function setScreen(id) {
  for (const s of ['menu', 'controls', 'select', 'fight', 'result']) {
    const el = $('screen-' + s);
    if (el) el.classList.toggle('hidden', s !== id);
  }
  Game.screen = id;
  const stage = $('stage');
  if (stage) stage.dataset.screen = id;
  const ui = $('ui');
  if (ui) ui.classList.toggle('interactive', id !== 'fight');
  const back = $('back-fab');
  if (back) back.hidden = id === 'menu';
  const pause = $('pause-fab');
  const restart = $('restart-fab');
  if (pause) pause.hidden = id !== 'fight';
  if (restart) restart.hidden = id !== 'fight';
  if (pause) {
    const paused = id === 'fight' && Game.paused;
    pause.setAttribute('aria-pressed', String(paused));
    pause.querySelector('.music-glyph').textContent = paused ? '▶' : 'Ⅱ';
    pause.querySelector('.music-label').textContent = paused ? 'CONTINUAR' : 'PAUSA';
  }
  Audio.init(); Audio.resume();
}

function renderSelect() {
  const grid = $('charGrid');
  if (!grid) return;
  const side = Game.selectSide;
  const state = side === 1 ? Game.p1 : Game.p2;
  $('selectPrompt').textContent = side === 1
    ? 'JUGADOR 1 · ELIGE PERSONAJE'
    : 'JUGADOR 2 · ELIGE PERSONAJE';
  grid.innerHTML = '';
  const isLocked = (c) => c.id === 'wzm' && !isMysticUnlocked()
    || c.id === 'mistikwiz' && !isMistikwizzUnlocked()
    || c.id === 'dcakuma' && !isDCAkumaUnlocked();
  const orderedRoster = ROSTER.map((c, originalIndex) => ({ c, originalIndex }))
    .sort((a, b) => Number(isLocked(a.c)) - Number(isLocked(b.c)));
  orderedRoster.forEach(({ c, originalIndex }) => {
    const locked = isLocked(c);
    const lockedMystic = c.id === 'wzm' && !isMysticUnlocked();
    const lockedMistikwizz = c.id === 'mistikwiz' && !isMistikwizzUnlocked();
    const lockedDCAkuma = c.id === 'dcakuma' && !isDCAkumaUnlocked();
    const idx = originalIndex;
    const el = document.createElement('div');
    el.className = 'char-card' + (state.focus === ROSTER.indexOf(c) ? ' focused' : '') + (locked ? ' locked' : '');
    el.dataset.char = c.id;
    el.style.setProperty('--char-accent', c.chroma);
    el.style.borderColor = c.chroma;
    const art = Art.get(c.id);
    const im = document.createElement('img');
    const unlockPoster = c.id === 'dcakuma' ? UNLOCK_ART.dcakuma : (c.id === 'wzm' ? UNLOCK_ART.wizz : null);
    const fr = art.frames[POSE[c.bank].idle];
    const portrait = SELECT_PORTRAITS[c.id];
    /* El póster solo representa el estado bloqueado; al desbloquear se
     * muestra el retrato externo si existe y, si no, el frame jugable real. */
    if (unlockPoster) {
      /* DCAKUMA y WIZZ MÍSTICO conservan la imagen especial de desbloqueo
       * también después de desbloquearse; no se sustituye por el retrato. */
      im.src = unlockPoster;
      im.style.objectFit = 'cover';
      im.style.opacity = locked ? '0.78' : '1';
    } else if (portrait) {
      im.src = portrait;
      im.style.objectFit = 'cover';
      im.style.opacity = '1';
    } else if (fr) {
      im.src = fr.src || (fr.toDataURL ? fr.toDataURL() : '');
      im.style.objectFit = 'contain';
      im.style.opacity = '1';
    }
    el.appendChild(im);
    /* Estas tres tarjetas usan TU.png como imagen de intriga y no muestran nombre. */
    const intrigueCard = c.id === 'dcb' || c.id === 'dcr';
    if (!intrigueCard) {
      const n = document.createElement('div');
      n.className = 'cname';
      n.textContent = lockedMystic ? 'BLOQUEADO · WIZZ MÍSTICO' : (lockedMistikwizz ? 'BLOQUEADO · MISTIKWIZZ' : (lockedDCAkuma ? 'BLOQUEADO · DCAKUMA' : c.name));
      el.appendChild(n);
    }
    el.onclick = () => { state.focus = ROSTER.indexOf(c); if (!locked) confirmPick(); else { Audio.sfx.menu(); renderSelect(); } };
    grid.appendChild(el);
  });
  /* Tarjeta sorpresa: entrega personajes normales o, tras desbloquearlos, los dos secretos. */
  const randomIdx = ROSTER.length;
  const randomPool = ROSTER.map((c) => c.id);
function pickRandomCardResult() {
  const roll = Math.random();
  const normal = () => CHAR[randomPool[Math.floor(Math.random() * randomPool.length)]];
  /* MIGUEL 1 y MIGUEL 2 no existen en tarjetas: permanecen secretos hasta
   * completar toda la ruta arcade. Después del desbloqueo, RANDOM conserva
   * exactamente 50% normal, 30% MIGUEL 1 y 20% MIGUEL 2. */
  if (roll < 0.50) return normal();
  if (!isMiguel1Unlocked() || !isMiguel2Unlocked()) return normal();
  if (roll < 0.80) return CHAR.miguel1;
  return CHAR.miguel2;
}
  const randomCard = document.createElement('div');
  randomCard.className = 'char-card crater-random-card' + (state.focus === randomIdx ? ' focused' : '');
  randomCard.dataset.char = 'crater-random';
  randomCard.style.background = 'radial-gradient(circle at 50% 35%, rgba(255,106,42,.58), rgba(18,7,42,.95) 70%)';
  randomCard.style.borderColor = '#ff6a2a';
  randomCard.innerHTML = '<div style="position:absolute;inset:0;display:grid;place-items:center;padding-bottom:26px;color:#ffd21f;font:900 clamp(48px,7vw,88px) Impact,sans-serif;text-shadow:0 4px 0 #000,0 0 18px #ff6a2a;">?</div><div class="cname">RANDOM · 50/30/20</div>';
  randomCard.onclick = () => { state.focus = randomIdx; confirmPick(); };
  grid.appendChild(randomCard);
  /* CPU o J2 en versus */
  if (Game.mode === 'versus') {
    const other = side === 1 ? Game.p2 : Game.p1;
    const o = $('otherTeam');
    if (o) o.innerHTML = other.picks.map((p) => `<span>${CHAR[p.charId].name}</span>`).join('') || '<span>PENDIENTE</span>';
  }
}

function confirmPick() {
  const side = Game.selectSide;
  const state = side === 1 ? Game.p1 : Game.p2;
  const c = state.focus === ROSTER.length ? pickRandomCardResult() : ROSTER[state.focus];
  if (state.focus !== ROSTER.length && ((c.id === 'wzm' && !isMysticUnlocked()) || (c.id === 'mistikwiz' && !isMistikwizzUnlocked()) || (c.id === 'dcakuma' && !isDCAkumaUnlocked()) || (c.id === 'miguel1' && !isMiguel1Unlocked()))) { renderSelect(); return; }
  state.picks = [{ charId: c.id }];
  Audio.sfx.select();
  if (state.picks.length < 1) { renderSelect(); return; }
  if (Game.mode === 'versus' && side === 1) {
    Game.selectSide = 2;
    Game.p2 = { picks: [], step: 0, focus: 0 };
    renderSelect();
    return;
  }
  Audio.sfx.ok();
  Game.beginFight();
}

/* ======================= BUCLE PRINCIPAL =============================== */

let accum = 0, lastTime = 0, running = false;

function frame(now) {
  requestAnimationFrame(frame);
  if (!lastTime) lastTime = now;
  let dt = (now - lastTime) / 1000;
  lastTime = now;
  if (dt > 0.25) dt = 0.25;
  accum += dt;

  Input.pollGamepads();

  let steps = 0;
  while (accum >= STEP && steps < MAX_STEP_FRAMES) {
    accumulateStep();
    accum -= STEP;
    steps++;
  }
  if (accum > STEP * MAX_STEP_FRAMES) accum = 0;

  render();
}

function accumulateStep() {
  const w = Game.world;
  if (!w || Game.screen !== 'fight') return;
  if (Game.paused) return;
  const inputs = Game.buildInputs();
  w.step(inputs);
  if (w.over && !w.finishedHandled) {
    w.finishedHandled = true;
    setTimeout(() => Game.onFightEnd(), 1600);
  }
}

function render() {
  const g = ctx;
  const w = Game.world;
  if (Game.screen === 'fight' && w) {
    drawFight(g, w);
    HUD.draw(g, w);
    if (Game.paused) {
      g.save();
      g.fillStyle = 'rgba(2,3,14,0.7)';
      g.fillRect(0, 0, VW, VH);
      g.textAlign = 'center';
      g.font = '900 90px Impact, sans-serif';
      g.fillStyle = '#ffd21f';
      g.strokeStyle = '#000'; g.lineWidth = 12;
      g.strokeText('PAUSA', VW / 2, VH / 2);
      g.fillText('PAUSA', VW / 2, VH / 2);
      g.font = '900 24px Impact, sans-serif';
      g.fillStyle = '#8fe6ff';
      g.fillText('P PARA CONTINUAR · ESC PARA EL MENÚ', VW / 2, VH / 2 + 54);
      g.restore();
    }
  } else {
    drawAttract(g);
  }
}

function drawAttract(g) {
  g.fillStyle = '#04051a';
  g.fillRect(0, 0, VW, VH);
  if (STAGE_BG.complete && STAGE_BG.naturalWidth > 0) {
    g.save();
    g.globalAlpha = 0.5;
    const natW = STAGE_BG.naturalWidth, natH = STAGE_BG.naturalHeight;
    const scale = Math.max(VW / natW, VH / natH);
    g.drawImage(STAGE_BG, (VW - natW * scale) / 2, (VH - natH * scale) / 2, natW * scale, natH * scale);
    g.restore();
  }
}

/* ======================= ENLACES DE INTERFAZ =========================== */

function installBindings() {
  document.querySelectorAll('[data-action]').forEach((btn) => {
    btn.addEventListener('click', () => {
      Audio.init(); Audio.resume();
      const a = btn.dataset.action;
      Audio.sfx.menu();
      if (a === 'arcade') Game.startMode('arcade');
      else if (a === 'versus') Game.startMode('versus');
      else if (a === 'practice') Game.startMode('practice');
      else if (a === 'controls') setScreen('controls');
      else if (a === 'menu') { Game.world = null; setScreen('menu'); }
      else if (a === 'continue') {
        if (Game.mode === 'arcade') {
          if (Game.arcadeComplete) { Game.world = null; Game.arcadeComplete = false; setScreen('menu'); }
          else Game.advanceArcade();
        } else if (Game.mode === 'versus' || Game.mode === 'practice') Game.beginFight();
        else setScreen('menu');
      }
    });
  });

  const back = $('back-fab');
  if (back) back.addEventListener('click', () => { Audio.sfx.menu(); Game.world = null; setScreen('menu'); });

  const pause = $('pause-fab');
  if (pause) pause.addEventListener('click', (e) => {
    e.preventDefault();
    if (Game.screen !== 'fight' || !Game.world || Game.world.over) return;
    Game.paused = !Game.paused;
    Audio.sfx.menu();
    setScreen('fight');
  });
  const restart = $('restart-fab');
  if (restart) restart.addEventListener('click', (e) => {
    e.preventDefault();
    if (Game.screen !== 'fight' || !Game.world) return;
    Game.beginFight();
    Audio.sfx.round();
  });

  const fullscreen = $('fullscreen-fab');
  if (fullscreen) {
    const syncFullscreen = () => {
      const active = document.fullscreenElement === $('cabinet');
      fullscreen.setAttribute('aria-pressed', String(active));
      fullscreen.querySelector('.music-label').textContent = active ? 'SALIR' : 'AMPLIAR';
      fullscreen.title = active ? 'Salir de pantalla completa' : 'Ampliar juego';
    };
    fullscreen.addEventListener('click', async (e) => {
      e.preventDefault();
      try {
        if (document.fullscreenElement) await document.exitFullscreen();
        else await $('cabinet').requestFullscreen();
      } catch (_) { /* El navegador puede bloquear fullscreen sin gesto válido. */ }
      syncFullscreen();
    });
    document.addEventListener('fullscreenchange', syncFullscreen);
    syncFullscreen();
  }

  const music = $('music-fab');
  if (music) {
    const syncMusicButton = () => {
      const playing = Audio.isMusicPlaying();
      music.setAttribute('aria-pressed', String(playing));
      music.classList.toggle('playing', playing);
      const label = music.querySelector('.music-label');
      if (label) label.textContent = playing ? 'PAUSAR' : 'ROLA2';
      music.title = playing ? 'Pausar música' : 'Reproducir música';
    };
    music.addEventListener('click', (e) => {
      e.preventDefault();
      Audio.init(); Audio.resume();
      if (Audio.isMusicPlaying()) Audio.stopMusic(); else Audio.startMusic();
      syncMusicButton();
    });
    syncMusicButton();
  }

  window.addEventListener('keydown', (e) => {
    const k = e.key.toLowerCase();
    Audio.init(); Audio.resume();
    if (e.repeat && Game.screen !== 'fight') return;
    if (Game.screen === 'menu') {
      if (k === '1') Game.startMode('arcade');
      else if (k === '2') Game.startMode('versus');
      else if (k === '3') Game.startMode('practice');
      else if (k === '4') setScreen('controls');
    } else if (Game.screen === 'controls' || Game.screen === 'result') {
      if (k === 'escape') { Game.world = null; setScreen('menu'); }
      if (Game.screen === 'result' && (k === 'enter' || k === ' ')) $('btn-continue')?.click();
    } else if (Game.screen === 'select') {
      const state = Game.selectSide === 1 ? Game.p1 : Game.p2;
      const cardCount = ROSTER.length + 1;
      if (k === 'arrowleft' || k === 'a') { state.focus = (state.focus - 1 + cardCount) % cardCount; renderSelect(); Audio.sfx.menu(); }
      else if (k === 'arrowright' || k === 'd') { state.focus = (state.focus + 1) % cardCount; renderSelect(); Audio.sfx.menu(); }
      else if (k === 'arrowup' || k === 'w') { state.focus = (state.focus - 8 + cardCount) % cardCount; renderSelect(); Audio.sfx.menu(); }
      else if (k === 'arrowdown' || k === 's') { state.focus = (state.focus + 8) % cardCount; renderSelect(); Audio.sfx.menu(); }
      else if (k === 'j' || k === 'enter' || k === ' ') confirmPick();
      else if (k === 'escape') { Game.reset(); setScreen('menu'); }
    } else if (Game.screen === 'fight') {
      if (k === 'escape') { Game.world = null; setScreen('menu'); }
      if (k === 'p') { Game.paused = !Game.paused; setScreen('fight'); }
    }
  });
}

/* ======================= ARRANQUE ====================================== */

const canvas = $('game');
const ctx = canvas.getContext('2d');
let bootFinished = false;
function revealMenuAfterBoot() {
  const loader = $('loader');
  if (loader) loader.style.display = 'none';
  try { installBindings(); } catch (err) { console.error('No se pudo instalar un binding opcional:', err); }
  try { setScreen('menu'); } catch (err) {
    console.error('No se pudo activar el menú:', err);
    document.querySelectorAll('.screen').forEach((el) => el.classList.add('hidden'));
    $('screen-menu')?.classList.remove('hidden');
    Game.screen = 'menu';
  }
  requestAnimationFrame(frame);
}
/* Recuperación: una imagen o paleta defectuosa no puede dejar el juego
 * permanentemente en CARGANDO. */
const bootWatchdog = setTimeout(() => {
  if (bootFinished) return;
  bootFinished = true;
  console.warn('Arranque recuperado por watchdog');
  revealMenuAfterBoot();
}, 8000);
(async () => {
  const bar = $('loaderBar');
  try {
    await Art.load((p) => { if (bar) bar.style.width = Math.round(p * 100) + '%'; });
  } catch (err) {
    console.error('Error preparando sprites:', err);
  }
  if (bootFinished) return;
  bootFinished = true;
  clearTimeout(bootWatchdog);
  revealMenuAfterBoot();
})();
